window.BANK['s5']['s5-1-1'] = [
  {"q":"التصنيف هو:","o":["عدّ المخلوقات الحية","تقسيم المخلوقات الحية حسب درجة التشابه","تسمية المخلوقات بأسماء عشوائية","جمع المخلوقات في مكان واحد"],"a":1,"why":"التصنيف هو تقسيم المخلوقات الحية إلى مجموعات بحسب درجة التشابه بينها في الصفات. ولأن عدد المخلوقات بالملايين نصنّفها في مجموعات لتسهل دراستها وتمييزها.","ow":["عدّ المخلوقات لا يسمى تصنيفًا؛ التصنيف تقسيمها إلى مجموعات بحسب التشابه.","","التسمية العشوائية لا علاقة لها بالتصنيف؛ يعتمد التصنيف على تشابه الصفات.","جمع المخلوقات في مكان واحد لا يُعدّ تصنيفًا؛ نقسّمها بحسب التشابه."]},
  {"q":"كم عدد الممالك التي تُصنَّف إليها المخلوقات الحية؟","o":["ثلاث ممالك","أربع ممالك","سبع ممالك","ست ممالك"],"a":3,"why":"تُصنَّف المخلوقات الحية إلى ست ممالك هي: الحيوانية والنباتية والفطريات والبدائيات والبكتيريا والطلائعيات.","ow":["ثلاث ممالك عدد أقل من الحقيقي؛ الممالك ست.","أربع ممالك عدد أقل من الحقيقي؛ الممالك ست.","سبع ممالك عدد أكبر من الحقيقي؛ الممالك ست، والفيروسات لا تدخل فيها.",""]},
  {"q":"أي مما يأتي من الممالك الست؟","o":["مملكة الفطريات","مملكة الفيروسات","مملكة الأسماك","مملكة الحشرات"],"a":0,"why":"الممالك الست هي الحيوانية والنباتية والفطريات والبدائيات والبكتيريا والطلائعيات، فمملكة الفطريات منها.","ow":["","الفيروسات لا تُصنَّف ضمن الممالك الست.","الأسماك فقاريات تتبع المملكة الحيوانية، وليست مملكة مستقلة.","الحشرات لافقاريات تتبع المملكة الحيوانية، وليست مملكة مستقلة."]},
  {"q":"أي الترتيبات الآتية يبدأ من أكبر مستوى إلى أصغر مستوى؟","o":["نوع ← جنس ← فصيلة ← رتبة ← طائفة ← شعبة ← مملكة","مملكة ← طائفة ← شعبة ← رتبة ← فصيلة ← جنس ← نوع","مملكة ← شعبة ← طائفة ← رتبة ← فصيلة ← جنس ← نوع","مملكة ← شعبة ← رتبة ← طائفة ← جنس ← فصيلة ← نوع"],"a":2,"why":"مستويات التصنيف من الأكبر إلى الأصغر: مملكة ← شعبة ← طائفة ← رتبة ← فصيلة ← جنس ← نوع. نبدأ بالمملكة لأنها أكبر مستوى وننتهي بالنوع لأنه أصغر مستوى.","ow":["هذا الترتيب معكوس؛ يبدأ بالنوع وهو أصغر مستوى.","هذا الترتيب وضع الطائفة قبل الشعبة؛ والصحيح شعبة ثم طائفة.","","هذا الترتيب بدّل مكان الطائفة والرتبة وبدّل الجنس والفصيلة؛ والصحيح طائفة ← رتبة ← فصيلة ← جنس."]},
  {"q":"الاسم العلمي للمخلوق الحي يُكوَّن من اسمين هما:","o":["اسم المملكة واسم الشعبة","اسم الرتبة واسم الفصيلة","اسم الجنس واسم النوع","اسم الطائفة واسم الجنس"],"a":2,"why":"الاسم العلمي للمخلوق الحي يتكوّن من اسمين هما الجنس والنوع، أي أصغر مستويين في التصنيف.","ow":["المملكة والشعبة مستويان كبيران وليسا اسم المخلوق العلمي.","الرتبة والفصيلة مستويان أكبر من الجنس والنوع ولا يُكوّنان الاسم العلمي.","","الطائفة مستوى كبير؛ الاسم العلمي يتكوّن من الجنس والنوع فقط."]},
  {"q":"السمكة والبقرة والثعبان من:","o":["الفقاريات","اللافقاريات","الفطريات","الطلائعيات"],"a":0,"why":"السمكة والبقرة والثعبان جميعها لها عمود فقري، والحيوانات التي لها عمود فقري تسمى الفقاريات.","ow":["","اللافقاريات حيوانات ليس لها عمود فقري، وهذه المخلوقات لها عمود فقري.","الفطريات ليست حيوانات؛ هي مملكة أخرى.","الطلائعيات مملكة مختلفة، وهذه المخلوقات من المملكة الحيوانية."]},
  {"q":"أي المخلوقات الآتية ليس له عمود فقري؟","o":["السمكة","البقرة","الثعبان","الإسفنج"],"a":3,"why":"الإسفنج حيوان لافقاري أي ليس له عمود فقري، أما السمكة والبقرة والثعبان فهي فقاريات لها عمود فقري.","ow":["السمكة فقارية ولها عمود فقري.","البقرة فقارية ولها عمود فقري.","الثعبان فقاري وله عمود فقري.",""]},
  {"q":"أي النباتات الآتية له أوعية نقل؟","o":["الحزاز","الطلح","حشيشة الكبد"],"a":1,"why":"الطلح نبات وعائي أي له أوعية تنقل الماء والغذاء، أما الحزاز وحشيشة الكبد فنباتان لاوعائيان ليس لهما أوعية نقل.","ow":["الحزاز نبات لاوعائي ليس له أوعية نقل.","","حشيشة الكبد نبات لاوعائي ليس له أوعية نقل."]},
  {"q":"حشيشة الكبد والحزاز من النباتات:","o":["التي ليس لها أوعية نقل","التي لها أوعية نقل","التي تنتج الثمار","التي تعيش في الماء فقط"],"a":0,"why":"الحزاز وحشيشة الكبد من النباتات اللاوعائية، أي التي ليس لها أوعية نقل، فلا تنقل الماء والغذاء كما تفعل النباتات الوعائية.","ow":["","النباتات التي لها أوعية نقل تسمى الوعائية مثل الطلح.","إنتاج الثمار لا يحدد كون النبات وعائيًّا أو لا؛ هذان نباتان لاوعائيان.","النباتات اللاوعائية ليست خاصة بالماء، والمعيار هو غياب أوعية النقل."]},
  {"q":"عفن الخبز من مملكة:","o":["النباتات","الحيوانات","الفطريات","البكتيريا"],"a":2,"why":"عفن الخبز من مملكة الفطريات؛ فهو لا يصنع غذاءه بنفسه بل يتغذى على الخبز المتعفن في مكان رطب.","ow":["النباتات تصنع غذاءها بالبناء الضوئي وعفن الخبز لا يفعل ذلك.","الحيوانات مملكة مختلفة، وعفن الخبز لا يتحرك ولا يشبه الحيوان.","","البكتيريا مملكة أخرى مخلوقاتها وحيدة الخلية، وعفن الخبز فطر."]},
  {"q":"أين تعيش الفطريات غالبًا؟","o":["في أماكن جافة مشمسة","في أماكن رطبة مظلمة","في الينابيع الحارة فقط","في قاع المحيط فقط"],"a":1,"why":"الفطريات تعيش غالبًا في أماكن رطبة مظلمة، ولهذا ينمو عفن الخبز في المكان الرطب. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الأماكن الجافة المشمسة لا تناسب الفطريات التي تحب الرطوبة والظلام.","","الينابيع الحارة تعيش فيها البدائيات وليست الفطريات.","الفطريات لا تعيش في قاع المحيط فقط؛ تعيش غالبًا في أماكن رطبة مظلمة."]},
  {"q":"أي الخصائص الآتية تشترك فيها البدائيات والبكتيريا؟","o":["متعددة الخلايا ولها نواة","لها عمود فقري","تصنع غذاءها بالبناء الضوئي","وحيدة الخلية وليس لها نواة"],"a":3,"why":"البدائيات والبكتيريا مخلوقات وحيدة الخلية وليس لها نواة، وهذا ما يميّزها عن المخلوقات الأخرى.","ow":["المخلوقات متعددة الخلايا ذات النواة ليست البدائيات ولا البكتيريا.","العمود الفقري من صفات الحيوانات الفقارية وليس البدائيات أو البكتيريا.","البناء الضوئي لتصنيع الغذاء من صفات النباتات وليس من الصفات المشتركة بين البدائيات والبكتيريا.",""]},
  {"q":"البراميسيوم من مملكة:","o":["الفطريات","الطلائعيات","البكتيريا","النباتات"],"a":1,"why":"البراميسيوم من مملكة الطلائعيات، وهي مملكة مخلوقاتها بعضها يشبه النباتات وبعضها يشبه الحيوانات أو الفطريات.","ow":["الفطريات مثل عفن الخبز والخميرة وليس البراميسيوم.","","البكتيريا مملكة مخلوقاتها وحيدة الخلية بلا نواة، وليس البراميسيوم.","النباتات مملكة مختلفة تصنع غذاءها بالبناء الضوئي."]},
  {"q":"الطحالب الحمراء من الطلائعيات التي تشبه:","o":["الحيوانات","الفطريات","الفيروسات","النباتات"],"a":3,"why":"الطحالب الحمراء من الطلائعيات التي تشبه النباتات، لأنها تصنع غذاءها مثل النباتات. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الطلائعيات التي تشبه الحيوانات مثل البراميسيوم وليست الطحالب الحمراء.","الطلائعيات التي تشبه الفطريات مخلوقات أخرى وليست الطحالب الحمراء.","الفيروسات لا تُصنَّف ضمن الممالك الست أصلًا فلا تكون من الطلائعيات.",""]},
  {"q":"أي المخلوقات الآتية تسبب الزكام والحصبة؟","o":["الفيروسات","الفطريات","الطلائعيات","النباتات"],"a":0,"why":"الفيروسات هي التي تسبب أمراضًا مثل الزكام والحصبة، وهي لا تتكاثر إلا داخل خلية حية. ومن خلاصة الدرس: الفيروسات لا تُصنَّف ضمن الممالك.","ow":["","الفطريات تتغذى على مخلوقات ميتة أو متعفنة ولا تسبب الزكام والحصبة.","الطلائعيات ممالك تشبه النباتات والحيوانات ولا تسبب الزكام والحصبة.","النباتات تصنع غذاءها ولا تسبب الأمراض مثل الزكام والحصبة."]},
  {"q":"العبارة: المملكة هي أكبر مستوى في تصنيف المخلوقات الحية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. مستويات التصنيف سبعة مرتبة من الأكبر إلى الأصغر (مملكة، شعبة، طائفة، رتبة، فصيلة، جنس، نوع)، وأكبرها المملكة.","ow":["","هذه العبارة صحيحة وليست خطأ؛ مستويات التصنيف سبعة مرتبة من الأكبر إلى الأصغر (مملكة، شعبة، طائفة، رتبة، فصيلة، جنس، نوع)، وأكبرها المملكة."]},
  {"q":"العبارة: النوع هو أكبر مستوى في التصنيف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. النوع هو أصغر مستوى في التصنيف وليس أكبرها؛ أكبر مستوى هو المملكة. ومن خلاصة الدرس: أكبر مستوى: مملكة – أصغر مستوى: نوع.","ow":["هذه العبارة ليست صحيحة؛ النوع هو أصغر مستوى في التصنيف وليس أكبرها؛ أكبر مستوى هو المملكة.",""]},
  {"q":"العبارة: تُصنَّف الفيروسات ضمن مملكة البكتيريا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الفيروسات لا تُصنَّف ضمن أي مملكة من الممالك الست، فهي لا تقوم بوظائف الحياة الأساسية ولا تتكاثر إلا داخل خلية حية.","ow":["هذه العبارة ليست صحيحة؛ الفيروسات لا تُصنَّف ضمن أي مملكة من الممالك الست، فهي لا تقوم بوظائف الحياة الأساسية ولا تتكاثر إلا داخل خلية حية.",""]},
  {"q":"العبارة: تصنع الفطريات غذاءها بنفسها.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الفطريات لا تصنع غذاءها بنفسها، بل تحصل عليه من مخلوقات ميتة أو متعفنة. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["هذه العبارة ليست صحيحة؛ الفطريات لا تصنع غذاءها بنفسها، بل تحصل عليه من مخلوقات ميتة أو متعفنة.",""]},
  {"q":"العبارة: لا تتكاثر الفيروسات إلا داخل خلية حية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الفيروسات لا تتكاثر إلا داخل خلية حية، وهذا من أسباب عدم تصنيفها ضمن الممالك الست.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الفيروسات لا تتكاثر إلا داخل خلية حية، وهذا من أسباب عدم تصنيفها ضمن الممالك الست."]},
  {"q":"العبارة: تعيش البدائيات في ظروف قاسية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. البدائيات مخلوقات وحيدة الخلية تعيش في ظروف قاسية مثل الينابيع الحارة.","ow":["","هذه العبارة صحيحة وليست خطأ؛ البدائيات مخلوقات وحيدة الخلية تعيش في ظروف قاسية مثل الينابيع الحارة."]},
];
window.BANK['s5']['s5-1-2'] = [
  {"q":"أي مما يأتي تحتاجه النباتات؟","o":["ماء فقط","ضوء القمر","هواء وماء وضوء الشمس وغذاء","الملح والرمل فقط"],"a":2,"why":"تحتاج النباتات إلى الهواء والماء وضوء الشمس والغذاء لتعيش وتنمو؛ فهي تستعمل الهواء والماء وضوء الشمس في صنع غذائها.","ow":["الماء وحده لا يكفي؛ تحتاج النباتات أيضًا إلى هواء وضوء الشمس وغذاء.","النبات يحتاج إلى ضوء الشمس وليس ضوء القمر في صنع غذائه.","","الملح والرمل وحدهما لا يكفيان؛ المطلوب هواء وماء وضوء وغذاء."]},
  {"q":"تُصنَّف النباتات حسب:","o":["لون الأزهار","حجم الأوراق","طريقة نقل الماء والغذاء","عدد الثمار"],"a":2,"why":"تُصنَّف النباتات بحسب طريقة نقل الماء والغذاء فيها إلى نباتات لاوعائية (بلا أوعية نقل) ونباتات وعائية (لها أوعية نقل).","ow":["لون الأزهار ليس أساس تصنيف النباتات إلى وعائية ولاوعائية.","حجم الأوراق ليس أساس التصنيف؛ الأساس طريقة نقل الماء والغذاء.","","عدد الثمار لا يُستعمل في تصنيف النباتات إلى مجموعاتها الرئيسية."]},
  {"q":"الحزازيات من النباتات:","o":["اللاوعائية","الوعائية مغطاة البذور","الوعائية معراة البذور","اللابذرية الوعائية"],"a":0,"why":"الحزازيات نباتات لاوعائية صغيرة الحجم ليس لها أوعية نقل، ولذلك تعيش في أماكن رطبة. ومن خلاصة الدرس: وعائية (لها أوعية) ولاوعائية.","ow":["","مغطاة البذور نباتات وعائية تنتج أزهارًا وثمارًا والحزازيات لا تنتجها.","معراة البذور نباتات وعائية تنتج مخاريط والحزازيات لا تنتجها.","النباتات اللابذرية الوعائية مثل السرخسيات لها أوعية نقل، أما الحزازيات فبلا أوعية."]},
  {"q":"أي الخصائص الآتية للنباتات اللاوعائية؟","o":["طويلة جدًّا ولها أوعية نقل","تنتج مخاريط","تنتج أزهارًا وثمارًا","صغيرة الحجم وليس لها أوعية نقل"],"a":3,"why":"النباتات اللاوعائية صغيرة الحجم وليس لها أوعية نقل، فتنتقل المواد فيها من خلية إلى خلية.","ow":["الطويلة جدًّا ذات الأوعية هي النباتات الوعائية.","المخاريط تنتجها النباتات معراة البذور وليس اللاوعائية.","الأزهار والثمار تنتجها النباتات مغطاة البذور وليس اللاوعائية.",""]},
  {"q":"السرخسيات نباتات:","o":["مغطاة البذور","لابذرية تتكاثر بالأبواغ","معراة البذور","ليس لها أوعية نقل"],"a":1,"why":"السرخسيات نباتات وعائية لابذرية؛ أي لها أوعية نقل لكنها لا تنتج بذورًا، وتتكاثر بالأبواغ.","ow":["السرخسيات لا تنتج أزهارًا ولا ثمارًا ولا بذورًا فليست مغطاة البذور.","","معراة البذور تنتج بذورًا في مخاريط، والسرخسيات لا تنتج بذورًا.","للسرخسيات أوعية نقل فهي وعائية وليست بلا أوعية."]},
  {"q":"الكوسة والبامية من النباتات:","o":["مغطاة البذور","معراة البذور","اللابذرية","اللاوعائية"],"a":0,"why":"الكوسة والبامية نباتان وعائيان ينتجان أزهارًا وثمارًا، فهما من النباتات مغطاة البذور.","ow":["","معراة البذور لا تنتج أزهارًا ولا ثمارًا مثل الصنوبر.","اللابذرية لا تنتج بذورًا وهاتان تنتجانها في ثمارهما.","الكوسة والبامية نباتان وعائيان لهما أوعية نقل."]},
  {"q":"الصنوبر والعرعر من النباتات:","o":["مغطاة البذور","اللاوعائية","معراة البذور","اللابذرية"],"a":2,"why":"الصنوبر والعرعر نباتان وعائيان ينتجان البذور في مخاريط دون أزهار أو ثمار، فهما من النباتات معراة البذور.","ow":["مغطاة البذور تنتج أزهارًا وثمارًا والصنوبر لا ينتجها.","الصنوبر والعرعر نباتان وعائيان لهما أوعية نقل.","","اللابذرية لا تنتج بذورًا والصنوبر ينتج بذورًا في المخاريط."]},
  {"q":"من وظائف الجذر:","o":["البناء الضوئي","امتصاص الماء والأملاح المعدنية","إنتاج الأزهار","فقد الماء"],"a":1,"why":"من وظائف الجذر امتصاص الماء والأملاح المعدنية من التربة، وتثبيت النبات في التربة، وتخزين الغذاء.","ow":["البناء الضوئي يحدث في الأوراق وليس في الجذر.","","الأزهار تنتجها السيقان والأغصان وليس الجذر.","فقد الماء (النتح) يحدث من الثغور في الأوراق."]},
  {"q":"الجذر الذي يتكون من جذر رئيسي واحد غليظ يسمى:","o":["الجذر الليفي","الجذر الهوائي","الشعيرة الجذرية","الجذر الوتدي"],"a":3,"why":"الجذر الوتدي جذر رئيسي واحد غليظ يمتد عميقًا في التربة وتتفرع منه جذور صغيرة. ومن خلاصة الدرس: الجذر: يمتص الماء ويثبّت.","ow":["الجذور الليفية دقيقة ومتفرعة وليست جذرًا رئيسيًّا واحدًا.","الجذور الهوائية لا تمتد في التربة.","الشعيرة الجذرية جزء دقيق يمتص الماء وليست جذرًا رئيسيًّا.",""]},
  {"q":"الجذور الدقيقة المتفرعة تسمى:","o":["الجذور الوتدية","الجذور الليفية","الجذور الهوائية","الجذور الثغرية"],"a":1,"why":"الجذور الليفية جذور دقيقة متفرعة تنتشر قريبًا من سطح التربة وليس لها جذر رئيسي غليظ. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الجذر الوتدي جذر رئيسي واحد غليظ.","","الجذور الهوائية لا تمتد في التربة.","لا يوجد نوع من الجذور اسمه الجذور الثغرية؛ الثغور في الأوراق."]},
  {"q":"الجذور التي لا تمتد في التربة تسمى:","o":["الجذور الوتدية","الجذور الليفية","الشعيرات الجذرية","الجذور الهوائية"],"a":3,"why":"الجذور الهوائية لا تمتد في التربة، بل تنمو في الهواء فوق سطح التربة كما في نباتات الغابة المطيرة.","ow":["الجذور الوتدية تمتد عميقًا داخل التربة.","الجذور الليفية تنتشر داخل التربة.","الشعيرات الجذرية أجزاء دقيقة من الجذر تمتص الماء وليست نوعًا مستقلًّا من الجذور.",""]},
  {"q":"الثغور هي:","o":["ثقوب في سطح الورقة","أوعية في الجذر","جزء من الزهرة","طبقة في الساق"],"a":0,"why":"الثغور ثقوب صغيرة في سطح الورقة (غالبًا السفلي) تتحكم فيها الخلايا الحارسة، ومنها يخرج الماء في النتح.","ow":["","أوعية الجذر هي الخشب واللحاء وليست الثغور.","الثغور توجد في الأوراق وليست جزءًا من الزهرة.","الثغور ثقوب في الورقة وليست طبقة في الساق."]},
  {"q":"أي مما يأتي يحتاجه البناء الضوئي؟","o":["أكسجين وسكر فقط","ماء وتراب فقط","ضوء وماء وثاني أكسيد الكربون","ضوء القمر والملح"],"a":2,"why":"يحتاج البناء الضوئي إلى ضوء الشمس والماء وثاني أكسيد الكربون لصنع السكر وإطلاق الأكسجين.","ow":["الأكسجين والسكر هما ناتجا البناء الضوئي وليسا من مواده.","التراب ليس مادة يحتاجها البناء الضوئي؛ يحتاج الماء وثاني أكسيد الكربون والضوء.","","يحتاج البناء الضوئي إلى ضوء الشمس وليس ضوء القمر."]},
  {"q":"ينتج عن البناء الضوئي:","o":["ماء وثاني أكسيد الكربون","نيتروجين وملح","سكر وأكسجين","بذور وأزهار"],"a":2,"why":"ينتج عن البناء الضوئي السكر (الغذاء) والأكسجين: ثاني أكسيد الكربون + ماء ← (ضوء) ← سكر + أكسجين.","ow":["الماء وثاني أكسيد الكربون من مواد البناء الضوئي وليسا من نواتجه.","النيتروجين والملح ليسا من نواتج البناء الضوئي.","","البذور والأزهار أجزاء تنتجها النباتات الزهرية وليست ناتج البناء الضوئي."]},
  {"q":"فقد الماء عن طريق الثغور يسمى:","o":["النتح","البناء الضوئي","الإخصاب","التلقيح"],"a":0,"why":"النتح هو فقد الماء من النبات على هيئة بخار عن طريق الثغور. ومن خلاصة الدرس: الجذر: يمتص الماء ويثبّت.","ow":["","البناء الضوئي هو صنع الغذاء في الأوراق.","الإخصاب عملية في التكاثر وليس فقد الماء.","التلقيح انتقال حبوب اللقاح وليس فقد الماء."]},
  {"q":"أي الأجزاء الآتية تتحكم في فتح الثغور وإغلاقها؟","o":["الشعيرات الجذرية","الكامبيوم","البتلات","الخلايا الحارسة"],"a":3,"why":"الخلايا الحارسة هي التي تفتح الثغور وتغلقها فتتحكم في خروج الماء من الورقة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الشعيرات الجذرية تمتص الماء من التربة وليست مسؤولة عن الثغور.","الكامبيوم طبقة تفصل بين الخشب واللحاء.","البتلات أجزاء من الزهرة ولا علاقة لها بالثغور.",""]},
  {"q":"العبارة: للنباتات الوعائية أوعية نقل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. النباتات الوعائية لها أوعية نقل (الخشب واللحاء) تنقل الماء والغذاء إلى أجزاء النبات.","ow":["","هذه العبارة صحيحة وليست خطأ؛ النباتات الوعائية لها أوعية نقل (الخشب واللحاء) تنقل الماء والغذاء إلى أجزاء النبات."]},
  {"q":"العبارة: تنتج النباتات معراة البذور أزهارًا وثمارًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. النباتات معراة البذور لا تنتج أزهارًا ولا ثمارًا، بل تنتج بذورها في مخاريط مثل الصنوبر؛ أما مغطاة البذور فهي التي تنتج الأزهار والثمار.","ow":["هذه العبارة ليست صحيحة؛ النباتات معراة البذور لا تنتج أزهارًا ولا ثمارًا، بل تنتج بذورها في مخاريط مثل الصنوبر؛ أما مغطاة البذور فهي التي تنتج الأزهار والثمار.",""]},
  {"q":"العبارة: الأوراق هي مكان البناء الضوئي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الأوراق هي مكان البناء الضوئي، فيها يُصنع الغذاء من الضوء والماء وثاني أكسيد الكربون.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الأوراق هي مكان البناء الضوئي، فيها يُصنع الغذاء من الضوء والماء وثاني أكسيد الكربون."]},
  {"q":"العبارة: تمتص الشعيرات الجذرية الماء من التربة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الشعيرات الجذرية أجزاء دقيقة في الجذر تمتص الماء والأملاح المعدنية من التربة.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الشعيرات الجذرية أجزاء دقيقة في الجذر تمتص الماء والأملاح المعدنية من التربة."]},
  {"q":"العبارة: الحزازيات من النباتات الوعائية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الحزازيات من النباتات اللاوعائية التي ليس لها أوعية نقل، وليست وعائية. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["هذه العبارة ليست صحيحة؛ الحزازيات من النباتات اللاوعائية التي ليس لها أوعية نقل، وليست وعائية.",""]},
];
window.BANK['s5']['s5-2-1'] = [
  {"q":"التكاثر هو:","o":["موت الأفراد القديمة","إنتاج أفراد جديدة من النوع نفسه","تغيّر شكل الفرد","انتقال الفرد من مكان لآخر"],"a":1,"why":"التكاثر هو إنتاج أفراد جديدة من النوع نفسه، وبه ينتقل النوع من جيل إلى جيل ولا ينقرض.","ow":["موت الأفراد القديمة ليس تكاثرًا؛ التكاثر إنتاج أفراد جديدة.","","تغيّر شكل الفرد هو نمو وليس تكاثرًا.","انتقال الفرد من مكان إلى آخر هجرة وليس تكاثرًا."]},
  {"q":"ما الذي ينتقل من الآباء إلى الأبناء في التكاثر؟","o":["المادة الوراثية","الغذاء فقط","الماء","الأحافير"],"a":0,"why":"في التكاثر تنتقل المادة الوراثية من الآباء إلى الأبناء، ولهذا تشبه الأبناء آباءها في صفات كثيرة.","ow":["","الغذاء يتناوله الفرد ولا ينتقل كمادة وراثية من الآباء.","الماء ليس مادة وراثية.","الأحافير بقايا مخلوقات قديمة وليست مادة وراثية."]},
  {"q":"نوعا التكاثر هما:","o":["الخضري والبذري","السريع والبطيء","الجنسي واللاجنسي","الداخلي والخارجي"],"a":2,"why":"للتكاثر نوعان: الجنسي (أبوان) واللاجنسي (أب واحد). ومن خلاصة الدرس: التكاثر: إنتاج أفراد جديدة.","ow":["الخضري نوع من التكاثر اللاجنسي في النباتات، والبذري غير مذكور كنوعين رئيسيين.","السريع والبطيء وصف لسرعة التكاثر وليس نوعيه.","","الداخلي والخارجي يصفان مكان الإخصاب وليسا نوعي التكاثر."]},
  {"q":"عدد الأبوين في التكاثر الجنسي:","o":["واحد","اثنان","ثلاثة","لا يوجد"],"a":1,"why":"التكاثر الجنسي يحتاج إلى أبوين؛ مشيج مذكّر من الأب ومشيج مؤنث من الأم يتحدان. ومن خلاصة الدرس: التكاثر: إنتاج أفراد جديدة.","ow":["أب واحد فقط في التكاثر اللاجنسي.","","ثلاثة آباء غير موجودة في أي نوع من التكاثر الجنسي.","لا بد من أبوين في التكاثر الجنسي."]},
  {"q":"الخلية التي تنتج عن اتحاد المشيجين تسمى:","o":["برعمًا","ساقًا جارية","بويضة","خلية مخصبة"],"a":3,"why":"اتحاد المشيج المذكّر والمشيج المؤنث (الإخصاب) ينتج خلية مخصّبة تنمو إلى فرد جديد. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["البرعم ينمو من جسم الأب في التبرعم وليس من اتحاد المشيجين.","الساق الجارية ساق نبات الفراولة تتكاثر بها خضريًّا.","البويضة هي المشيج المؤنث قبل الإخصاب وليست الخلية الناتجة عنه.",""]},
  {"q":"في التكاثر اللاجنسي يكون الأبناء:","o":["مختلفين تمامًا","مطابقين للأب","من أبوين","أكثر تنوعًا دائمًا"],"a":1,"why":"في التكاثر اللاجنسي يوجد أب واحد فقط، فيكون الأبناء مطابقين له في صفاتهم. ومن خلاصة الدرس: التكاثر: إنتاج أفراد جديدة.","ow":["الأبناء في اللاجنسي يشبهون الأب ولا يختلفون عنه تمامًا.","","الأبوان من خصائص التكاثر الجنسي.","التنوع الدائم من ميزة التكاثر الجنسي."]},
  {"q":"أي مما يأتي لا يحدث في التكاثر اللاجنسي؟","o":["وجود أب واحد","إنتاج أبناء مطابقين","الانقسام","اتحاد الخلايا الجنسية"],"a":3,"why":"لا يحدث اتحاد الخلايا الجنسية في التكاثر اللاجنسي؛ فهو يحدث في التكاثر الجنسي. أما الأب الواحد والأبناء المطابقون والانقسام فمن صفاته.","ow":["وجود أب واحد من صفات التكاثر اللاجنسي.","إنتاج أبناء مطابقين للأب من صفات اللاجنسي.","الانقسام إحدى طرق التكاثر اللاجنسي.",""]},
  {"q":"في الانقسام تنقسم الخلية الواحدة إلى:","o":["خليتين","ثلاث خلايا","أربع خلايا","برعم"],"a":0,"why":"في الانقسام تنقسم الخلية الواحدة إلى خليتين، بعد أن تتضاعف المادة الوراثية. ومن خلاصة الدرس: طرق اللاجنسي: انقسام – تبرعم – خضري.","ow":["","الانقسام ينتج خليتين وليس ثلاثًا.","الانقسام ينتج خليتين وليس أربعًا.","البرعم يرتبط بالتبرعم وليس بالانقسام."]},
  {"q":"ماذا يحدث للمادة الوراثية قبل الانقسام؟","o":["تختفي","تنقص إلى النصف","تتضاعف","تتحول إلى برعم"],"a":2,"why":"قبل الانقسام تتضاعف المادة الوراثية حتى تحصل كل خلية جديدة على نسخة كاملة منها. ومن خلاصة الدرس: طرق اللاجنسي: انقسام – تبرعم – خضري.","ow":["المادة الوراثية لا تختفي قبل الانقسام.","المادة الوراثية لا تنقص إلى النصف قبل الانقسام بل تتضاعف.","","المادة الوراثية لا تتحول إلى برعم."]},
  {"q":"بعض أنواع البكتيريا ينقسم كل:","o":["20 ساعة تقريبًا","20 يومًا تقريبًا","20 دقيقة تقريبًا","20 سنة تقريبًا"],"a":2,"why":"بعض أنواع البكتيريا تنقسم كل 20 دقيقة تقريبًا، ولذلك يزداد عددها بسرعة كبيرة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["20 ساعة وقت أطول بكثير من الحقيقي.","20 يومًا وقت أطول بكثير من الحقيقي.","","20 سنة وقت أطول بكثير من الحقيقي."]},
  {"q":"في التبرعم ينمو برعم من:","o":["جسم المخلوق الأب","بذرة","ورقة فقط","مشيج"],"a":0,"why":"في التبرعم ينمو برعم من جسم المخلوق الأب، ثم ينفصل عنه ويصير مخلوقًا جديدًا. ومن خلاصة الدرس: طرق اللاجنسي: انقسام – تبرعم – خضري.","ow":["","البذرة تنتج عن التكاثر الجنسي في النباتات وليست مصدر البرعم.","الورقة تُستعمل في التكاثر الخضري وليس في التبرعم.","المشيج خلية جنسية وليست مصدر البرعم."]},
  {"q":"أي المخلوقات الآتية تتكاثر بالتبرعم؟","o":["البكتيريا","الفراشة","الضفدع","الخميرة"],"a":3,"why":"الخميرة تتكاثر بالتبرعم؛ ينمو برعم من جسمها ثم ينفصل. ومن أمثلته الهيدرا والإسفنجيات.","ow":["البكتيريا تتكاثر بالانقسام.","الفراشة تتكاثر جنسيًّا.","الضفدع يتكاثر جنسيًّا.",""]},
  {"q":"التكاثر الخضري يحدث في:","o":["الطيور","النباتات","الأسماك","الزواحف"],"a":1,"why":"التكاثر الخضري يحدث في النباتات، فينتج نبات جديد من ورقة أو جذر أو ساق دون بذور. ومن خلاصة الدرس: التكاثر: إنتاج أفراد جديدة.","ow":["الطيور تتكاثر جنسيًّا.","","الأسماك تتكاثر جنسيًّا.","الزواحف تتكاثر جنسيًّا."]},
  {"q":"الساق الجارية في الفراولة مثال على التكاثر:","o":["الخضري","الجنسي","بالانقسام","بالتبرعم"],"a":0,"why":"الساق الجارية في الفراولة مثال على التكاثر الخضري، إذ ينمو منها نبات جديد دون بذور. ومن خلاصة الدرس: التكاثر: إنتاج أفراد جديدة.","ow":["","التكاثر الجنسي يحتاج إلى أبوين وإخصاب.","الانقسام تكاثر خلية واحدة إلى خليتين كما في البكتيريا.","التبرعم ينمو فيه برعم من الأب كما في الهيدرا."]},
  {"q":"في التكاثر الخضري ينتج نبات جديد من:","o":["بذرة فقط","زهرة فقط","ورقة أو جذر أو ساق","ثمرة فقط"],"a":2,"why":"في التكاثر الخضري ينتج نبات جديد من ورقة أو جذر أو ساق دون الحاجة إلى بذور. ومن خلاصة الدرس: التكاثر: إنتاج أفراد جديدة.","ow":["التكاثر الخضري لا يحتاج إلى بذرة.","الزهرة وحدها ليست مصدر التكاثر الخضري.","","الثمرة وحدها ليست مصدر التكاثر الخضري."]},
  {"q":"من ميزات التكاثر الجنسي:","o":["تطابق الأبناء مع الأب","تنوع الصفات وفرصة أكبر للتكيف","سرعة الانقسام","عدم الحاجة إلى أبوين"],"a":1,"why":"من ميزات التكاثر الجنسي أنه يحقق تنوعًا في صفات المخلوقات، مما يعطيها فرصة أكبر للتكيف مع تغيّرات البيئة.","ow":["تطابق الأبناء مع الأب من صفات التكاثر اللاجنسي.","","سرعة الانقسام ميزة التكاثر اللاجنسي في البكتيريا.","التكاثر الجنسي يحتاج إلى أبوين."]},
  {"q":"العبارة: يوجد التكاثر اللاجنسي في الممالك الست.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. التكاثر اللاجنسي موجود في الممالك الست كلها، فكل مملكة فيها مخلوقات تتكاثر لاجنسيًّا.","ow":["","هذه العبارة صحيحة وليست خطأ؛ التكاثر اللاجنسي موجود في الممالك الست كلها، فكل مملكة فيها مخلوقات تتكاثر لاجنسيًّا."]},
  {"q":"العبارة: يحتاج التكاثر الخضري إلى بذور.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. التكاثر الخضري لا يحتاج إلى بذور؛ إذ ينتج نبات جديد من ورقة أو جذر أو ساق.","ow":["هذه العبارة ليست صحيحة؛ التكاثر الخضري لا يحتاج إلى بذور؛ إذ ينتج نبات جديد من ورقة أو جذر أو ساق.",""]},
  {"q":"العبارة: يحدث الإخصاب في التكاثر الجنسي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الإخصاب هو اتحاد المشيج المذكّر بالمشيج المؤنث، ويحدث في التكاثر الجنسي.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الإخصاب هو اتحاد المشيج المذكّر بالمشيج المؤنث، ويحدث في التكاثر الجنسي."]},
  {"q":"العبارة: في التكاثر اللاجنسي يوجد أبوان.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. في التكاثر اللاجنسي يوجد أب واحد فقط، أما الأبوان فمن صفات التكاثر الجنسي.","ow":["هذه العبارة ليست صحيحة؛ في التكاثر اللاجنسي يوجد أب واحد فقط، أما الأبوان فمن صفات التكاثر الجنسي.",""]},
  {"q":"العبارة: تتكاثر البكتيريا بالانقسام.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. البكتيريا تتكاثر بالانقسام، فتنقسم الخلية الواحدة إلى خليتين بعد تضاعف المادة الوراثية.","ow":["","هذه العبارة صحيحة وليست خطأ؛ البكتيريا تتكاثر بالانقسام، فتنقسم الخلية الواحدة إلى خليتين بعد تضاعف المادة الوراثية."]},
];
window.BANK['s5']['s5-2-2'] = [
  {"q":"دورة الحياة هي:","o":["أسماء الحيوانات المتشابهة","عدد الأبناء","مكان الحياة","سلسلة مراحل النمو التي يمر بها المخلوق"],"a":3,"why":"دورة الحياة هي سلسلة مراحل النمو التي يمر بها المخلوق الحي، تبدأ من تكوّنه وتنتهي باكتمال نموه (البلوغ).","ow":["أسماء الحيوانات المتشابهة لا تمثل دورة الحياة.","عدد الأبناء لا يمثل دورة الحياة بل مراحل النمو.","مكان الحياة لا يمثل دورة الحياة بل مراحل النمو.",""]},
  {"q":"التحوّل في دورة الحياة يعني:","o":["تغيّر المكان","مراحل نمو مميزة مختلفة","تغيّر الغذاء فقط","زيادة الحجم فقط"],"a":1,"why":"التحوّل في دورة الحياة يعني أن المخلوق يمر بمراحل نمو مميزة مختلفة في شكلها، مثل بيضة ثم يرقة ثم عذراء ثم بالغة.","ow":["تغيّر المكان ليس تحولًا في دورة الحياة.","","تغيّر الغذاء وحده ليس التحول؛ التحول مراحل نمو مختلفة الشكل.","زيادة الحجم وحدها نمو وليست تحوّلًا."]},
  {"q":"أي التسلسلات الآتية يمثل التحول الكامل؟","o":["بيضة ← حورية ← بالغة","بيضة ← بالغة ← يرقة","يرقة ← بيضة ← عذراء","بيضة ← يرقة ← عذراء ← بالغة"],"a":3,"why":"التحول الكامل أربع مراحل مرتبة: بيضة ← يرقة ← عذراء ← بالغة. ومن خلاصة الدرس: تحوّل كامل (4 مراحل) – ناقص (3 مراحل).","ow":["بيضة ← حورية ← بالغة هو تسلسل التحول الناقص.","ترتيب خاطئ؛ تبدأ دورة الحياة بالبيضة ثم اليرقة.","ترتيب خاطئ؛ تبدأ دورة الحياة بالبيضة وليس اليرقة.",""]},
  {"q":"الفراشة تمر بتحول:","o":["كامل","ناقص","لا تمر بتحول","سلوكي"],"a":0,"why":"الفراشة تمر بتحول كامل: بيضة ثم يرقة ثم عذراء (داخل الشرنقة) ثم فراشة بالغة. ومن خلاصة الدرس: تحوّل كامل (4 مراحل) – ناقص (3 مراحل).","ow":["","التحول الناقص ثلاث مراحل لا يوجد فيها عذراء، كما في الجرادة.","الفراشة تمر بتحول فهي لا تولد بشكلها البالغ.","السلوكي ليس نوعًا من أنواع التحول."]},
  {"q":"عدد مراحل التحول الناقص:","o":["اثنتان","أربع","ثلاث","خمس"],"a":2,"why":"التحول الناقص ثلاث مراحل: بيضة ← حورية ← بالغة. ومن خلاصة الدرس: تحوّل كامل (4 مراحل) – ناقص (3 مراحل).","ow":["مرحلتان أقل من عدد مراحل التحول الناقص.","أربع مراحل هي عدد مراحل التحول الكامل.","","خمس مراحل أكثر من اللازم؛ الناقص ثلاث."]},
  {"q":"في التحول الناقص تأتي الحورية بعد:","o":["العذراء","اليرقة","البيضة","البالغة"],"a":2,"why":"في التحول الناقص تأتي الحورية بعد البيضة مباشرة ثم تصير بالغة: بيضة ← حورية ← بالغة. ومن خلاصة الدرس: تحوّل كامل (4 مراحل) – ناقص (3 مراحل).","ow":["لا توجد عذراء في التحول الناقص.","اليرقة من مراحل التحول الكامل وليس الناقص.","","البالغة آخر المراحل وتأتي بعد الحورية."]},
  {"q":"المخلوق الذي تتكون دورة حياته من بيضة وحورية وبالغة هو:","o":["الجرادة","الفراشة","الضفدع","الأسماك"],"a":0,"why":"الجرادة تمر بتحول ناقص: بيضة ثم حورية ثم بالغة، وليس فيها يرقة ولا عذراء. ومن خلاصة الدرس: دورة الحياة = مراحل النمو.","ow":["","الفراشة تمر بتحول كامل من أربع مراحل.","الضفدع يمر بمراحل مختلفة وليس مثالًا على التحول الناقص بهذا الاسم.","الأسماك ليست مثالًا على التحول الناقص بمراحل بيضة وحورية وبالغة."]},
  {"q":"الشرنقة تتكوّن حول:","o":["الحورية","البيضة","الحشرة البالغة","العذراء"],"a":3,"why":"الشرنقة تتكوّن حول العذراء، وهي مرحلة من مراحل التحول الكامل. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الحورية مرحلة في التحول الناقص ولا تتكوّن حولها شرنقة.","البيضة هي أول مرحلة ولا تتكوّن حولها شرنقة.","الحشرة البالغة هي آخر مرحلة وتخرج من الشرنقة.",""]},
  {"q":"المشيج المذكر في الحيوانات هو:","o":["اللاقحة","الحيوان المنوي","البيضة المخصبة","الكربلة"],"a":1,"why":"المشيج المذكر في الحيوانات هو الحيوان المنوي، ويتحد مع البويضة (المشيج المؤنث) في الإخصاب.","ow":["اللاقحة هي الخلية الناتجة عن اتحاد المشيجين.","","البيضة المخصبة هي اللاقحة نفسها.","الكربلة جزء أنثوي في الزهرة وليست مشيجًا مذكّرًا."]},
  {"q":"الخلية الناتجة عن اندماج المشيجين تسمى:","o":["اللاقحة (البيضة المخصبة)","الحورية","السداة","البرعم"],"a":0,"why":"الخلية الناتجة عن اندماج المشيج المذكر مع المشيج المؤنث تسمى اللاقحة أو البيضة المخصبة.","ow":["","الحورية مرحلة من مراحل التحول الناقص وليست خلية ناتجة عن الإخصاب.","السداة الجزء المذكر في الزهرة.","البرعم ينمو في التبرعم وليس عن اتحاد المشيجين."]},
  {"q":"الإخصاب الخارجي يحدث:","o":["داخل جسم الأنثى","في الأزهار فقط","خارج جسم الأنثى","بعد التلقيح فقط"],"a":2,"why":"الإخصاب الخارجي يحدث خارج جسم الأنثى، وغالبًا في الماء كما في الأسماك والضفادع. ومن خلاصة الدرس: إخصاب خارجي وداخلي.","ow":["الإخصاب داخل جسم الأنثى هو الإخصاب الداخلي.","الإخصاب في الأزهار ليس هو تعريف الإخصاب الخارجي.","","الإخصاب الخارجي لا يرتبط بالتلقيح في الزهرة."]},
  {"q":"أي المخلوقات الآتية إخصابها خارجي؟","o":["الطيور","الأسماك والضفادع","الزواحف","الثدييات"],"a":1,"why":"الأسماك والضفادع إخصابها خارجي، يحدث في الماء خارج جسم الأنثى. ومن خلاصة الدرس: إخصاب خارجي وداخلي.","ow":["الطيور إخصابها داخلي.","","الزواحف إخصابها داخلي.","الثدييات إخصابها داخلي."]},
  {"q":"أي المخلوقات الآتية إخصابها داخلي؟","o":["الأسماك","الضفادع","الطحالب","الطيور"],"a":3,"why":"الطيور إخصابها داخلي داخل جسم الأنثى، أما الأسماك والضفادع والطحالب فإخصابها خارجي. ومن خلاصة الدرس: إخصاب خارجي وداخلي.","ow":["الأسماك إخصابها خارجي في الماء.","الضفادع إخصابها خارجي في الماء.","الطحالب إخصابها خارجي في الماء.",""]},
  {"q":"بيض الزواحف والطيور يكون:","o":["بلا قشرة في الماء","له قشرة صلبة","داخل جسم الأم فقط","كثيرًا جدًّا"],"a":1,"why":"بيض الزواحف والطيور له قشرة صلبة تحميه، ويوضع غالبًا على اليابسة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["بيض الأسماك والضفادع هو الذي يوضع في الماء وليس لها قشرة صلبة.","","معظم الثدييات هي التي ينمو الجنين فيها داخل جسم الأم.","«كثيرًا جدًّا» لا يصف قشرة البيض؛ صفة بيض الزواحف والطيور قشرته الصلبة."]},
  {"q":"الجزء المذكر في الزهرة هو:","o":["الكربلة","البتلة","الثغر","السداة"],"a":3,"why":"الجزء المذكر في الزهرة هو السداة، وفيها حبوب اللقاح. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الكربلة هي الجزء الأنثوي في الزهرة.","البتلة جزء ملوّن في الزهرة وليس الجزء المذكر.","الثغر ثقب في الورقة وليس جزءًا من الزهرة.",""]},
  {"q":"الجزء الأنثوي في الزهرة هو:","o":["الكربلة","السداة","الجذر","الورقة"],"a":0,"why":"الجزء الأنثوي في الزهرة هو الكربلة، وفيها تتكوّن البذور بعد التلقيح والإخصاب. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["","السداة هي الجزء المذكر في الزهرة.","الجذر ليس جزءًا من الزهرة.","الورقة ليست الجزء الأنثوي في الزهرة."]},
  {"q":"أي مما يأتي من الملقّحات؟","o":["الجذور","التربة","النحل","الكربلة"],"a":2,"why":"النحل والطيور والرياح من الملقّحات لأنها تنقل حبوب اللقاح من الزهرة إلى أخرى. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الجذور تمتص الماء ولا تنقل حبوب اللقاح.","التربة لا تنقل حبوب اللقاح.","","الكربلة جزء أنثوي في الزهرة وليست ناقلة لحبوب اللقاح."]},
  {"q":"يحدث بعد التلقيح والإخصاب في الزهرة:","o":["موت الزهرة فورًا","تكوّن الجذور فقط","تكوّن البذور","التحول الكامل"],"a":2,"why":"بعد التلقيح يحدث الإخصاب في الزهرة، ثم تتكوّن البذور. ومن خلاصة الدرس: التلقيح ثم الإخصاب في الأزهار.","ow":["الزهرة لا تموت فورًا بل تتكوّن فيها البذور.","لا تتكوّن الجذور فقط بعد التلقيح؛ تتكوّن البذور.","","التحول الكامل من مراحل نمو الحشرات وليس من الأزهار."]},
  {"q":"العبارة: التلقيح الذاتي يحدث داخل الزهرة نفسها.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. التلقيح الذاتي هو انتقال حبوب اللقاح داخل الزهرة نفسها (من سداتها إلى كربلتها).","ow":["","هذه العبارة صحيحة وليست خطأ؛ التلقيح الذاتي هو انتقال حبوب اللقاح داخل الزهرة نفسها (من سداتها إلى كربلتها)."]},
  {"q":"العبارة: التلقيح الخلطي يحدث بين زهرتين.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. التلقيح الخلطي هو انتقال حبوب اللقاح بين زهرتين، تنقلها الملقّحات كالنحل والطيور والرياح.","ow":["","هذه العبارة صحيحة وليست خطأ؛ التلقيح الخلطي هو انتقال حبوب اللقاح بين زهرتين، تنقلها الملقّحات كالنحل والطيور والرياح."]},
  {"q":"العبارة: يُطلق في الإخصاب الخارجي عدد قليل جدًّا من الأمشاج.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. يُطلق في الإخصاب الخارجي عدد كبير جدًّا من الأمشاج، لأن كثيرًا منها يتلف أو يتعرض لحرارة عالية.","ow":["هذه العبارة ليست صحيحة؛ يُطلق في الإخصاب الخارجي عدد كبير جدًّا من الأمشاج، لأن كثيرًا منها يتلف أو يتعرض لحرارة عالية.",""]},
  {"q":"العبارة: تمر الجرادة بتحول كامل.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الجرادة تمر بتحول ناقص (بيضة ثم حورية ثم بالغة) وليس كاملًا؛ فليس لها مرحلة عذراء.","ow":["هذه العبارة ليست صحيحة؛ الجرادة تمر بتحول ناقص (بيضة ثم حورية ثم بالغة) وليس كاملًا؛ فليس لها مرحلة عذراء.",""]},
  {"q":"العبارة: عدد البيض في الإخصاب الداخلي أقل منه في الخارجي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. في الإخصاب الداخلي يكون عدد البيض أقل منه في الإخصاب الخارجي، لأن فرصة نجاح الإخصاب أكبر داخل جسم الأنثى.","ow":["","هذه العبارة صحيحة وليست خطأ؛ في الإخصاب الداخلي يكون عدد البيض أقل منه في الإخصاب الخارجي، لأن فرصة نجاح الإخصاب أكبر داخل جسم الأنثى."]},
];
window.BANK['s5']['s5-3-1'] = [
  {"q":"العوامل الحيوية في النظام البيئي هي:","o":["المخلوقات الحية","الماء","التربة","ضوء الشمس"],"a":0,"why":"العوامل الحيوية في النظام البيئي هي المخلوقات الحية (نباتات وحيوانات وغيرها)، أما الماء والتربة والشمس فعوامل لاحيوية.","ow":["","الماء عامل لاحيوي لأنه غير حي.","التربة عامل لاحيوي لأنها غير حية.","ضوء الشمس عامل لاحيوي لأنه غير حي."]},
  {"q":"أي مما يأتي عامل لاحيوي؟","o":["النبات","الحيوان","البكتيريا","التربة"],"a":3,"why":"التربة عامل لاحيوي أي غير حي، مثل الماء وضوء الشمس. أما النبات والحيوان والبكتيريا فمخلوقات حية أي عوامل حيوية.","ow":["النبات مخلوق حي أي عامل حيوي.","الحيوان مخلوق حي أي عامل حيوي.","البكتيريا مخلوقات حية أي عوامل حيوية.",""]},
  {"q":"تتنافس المخلوقات الحية في النظام البيئي على:","o":["الأسماء","الموارد","الألوان","الأصوات"],"a":1,"why":"تتنافس المخلوقات الحية في النظام البيئي على الموارد مثل الغذاء والماء والمأوى. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الأسماء لا تتنافس عليها المخلوقات الحية.","","الألوان ليست موردًا تتنافس عليه المخلوقات.","الأصوات ليست موردًا تتنافس عليه المخلوقات."]},
  {"q":"السعة التحملية هي:","o":["أقصى عدد من أفراد الجماعة يدعمه النظام البيئي","أقل عدد من أفراد الجماعة","عدد أنواع النباتات","مساحة النظام البيئي"],"a":0,"why":"السعة التحملية هي أقصى عدد من أفراد الجماعة الحيوية يدعمه النظام البيئي ويوفّر له الغذاء والموارد.","ow":["","أقل عدد لا يمثل السعة التحملية؛ هي أقصى عدد.","عدد أنواع النباتات ليس هو السعة التحملية.","مساحة النظام البيئي ليست هي السعة التحملية."]},
  {"q":"ماذا يحدث إذا زاد عدد أفراد الجماعة على السعة التحملية؟","o":["يزداد الغذاء","لا يحدث شيء","يقل الغذاء ويموت بعض الأفراد","تتوقف الجماعة عن التنافس"],"a":2,"why":"إذا زاد عدد أفراد الجماعة على السعة التحملية يقل الغذاء والموارد لكل فرد فيموت بعض الأفراد.","ow":["الغذاء يقل وليس يزداد عند زيادة العدد على السعة التحملية.","يحدث شيء: يقل الغذاء ويموت بعض الأفراد.","","التنافس يزداد ولا يتوقف عند زيادة العدد."]},
  {"q":"أي مما يأتي عامل محدد حيوي؟","o":["الماء","المفترسات","درجة الحرارة","ضوء الشمس"],"a":1,"why":"المفترسات عامل محدد حيوي لأنها مخلوقات حية تحدّ من عدد أفراد الجماعة، أما الماء والحرارة وضوء الشمس فعوامل لاحيوية.","ow":["الماء عامل محدد لاحيوي.","","درجة الحرارة عامل محدد لاحيوي.","ضوء الشمس عامل محدد لاحيوي."]},
  {"q":"أي مما يأتي عامل محدد لاحيوي؟","o":["الغذاء","المفترسات","الأمراض","درجة الحرارة"],"a":3,"why":"درجة الحرارة عامل محدد لاحيوي لأنها ليست مخلوقًا حيًّا. أما الغذاء والمفترسات والأمراض فعوامل محددة حيوية.","ow":["الغذاء من العوامل المحددة الحيوية.","المفترسات عامل محدد حيوي.","الأمراض عامل محدد حيوي.",""]},
  {"q":"الموطن هو:","o":["دور المخلوق في النظام البيئي","المكان الذي يعيش فيه المخلوق ويحصل منه على الغذاء","عدد أفراد الجماعة","نوع الغذاء"],"a":1,"why":"الموطن هو المكان الذي يعيش فيه المخلوق ويحصل منه على الغذاء، أي (عنوانه). راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["دور المخلوق في النظام البيئي هو الإطار البيئي.","","عدد أفراد الجماعة ليس هو الموطن.","نوع الغذاء ليس هو الموطن."]},
  {"q":"الإطار البيئي هو:","o":["مكان المخلوق فقط","اسم المخلوق","عدد الأبناء","دور المخلوق في موطنه وظروفه المناسبة"],"a":3,"why":"الإطار البيئي هو دور المخلوق في موطنه وظروفه المناسبة له، أي (شغله) في النظام البيئي.","ow":["مكان المخلوق فقط هو الموطن.","اسم المخلوق ليس هو الإطار البيئي.","عدد الأبناء ليس هو الإطار البيئي.",""]},
  {"q":"لماذا تتجنب الطيور المنافسة وهي تعيش في الغابة نفسها؟","o":["لأن لكل طائر منقارًا مختلفًا وغذاءً مختلفًا","لأنها تأكل الغذاء نفسه","لأنها تعيش في أماكن مختلفة تمامًا","لأنها لا تحتاج إلى غذاء"],"a":0,"why":"الطيور في الغابة نفسها تتجنب التنافس لأن لكل طائر منقارًا مختلفًا فيأكل غذاءً مختلفًا، أي إطارًا بيئيًّا مختلفًا.","ow":["","لو أكلت الغذاء نفسه لتنافست.","هي تعيش في الغابة نفسها وليس في أماكن مختلفة تمامًا.","الطيور تحتاج إلى غذاء مثل بقية المخلوقات."]},
  {"q":"التكافل علاقة ممتدة بين نوعين أو أكثر يستفيد منها:","o":["الجميع دائمًا","لا أحد","واحد على الأقل","الطفيلي فقط دائمًا"],"a":2,"why":"التكافل علاقة ممتدة بين نوعين أو أكثر يستفيد منها واحد على الأقل منهما دون ضرر بالباقي.","ow":["الجميع لا يستفيد دائمًا؛ ففي التعايش يستفيد مخلوق واحد.","لا بد أن يستفيد واحد على الأقل.","","الطفيلي ليس الوحيد المستفيد دائمًا؛ هذا تعريف خاص بالتطفل."]},
  {"q":"من أشكال التكافل:","o":["التنافس والتبرعم","التبخر والتكثف","تبادل المنفعة والتعايش والتطفل","التلقيح والإخصاب"],"a":2,"why":"من أشكال التكافل: تبادل المنفعة والتعايش والتطفل. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["التنافس والتبرعم ليسا من أشكال التكافل.","التبخر والتكثف ظاهرتان في دورة الماء.","","التلقيح والإخصاب من مراحل التكاثر."]},
  {"q":"علاقة النمل بشجرة الأكاسيا مثال على:","o":["تبادل المنفعة","التعايش","التطفل","التنافس"],"a":0,"why":"النمل وشجرة الأكاسيا يستفيد كل منهما من الآخر، فهذه علاقة تبادل المنفعة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["","في التعايش يستفيد مخلوق ولا يتأثر الآخر.","في التطفل يستفيد الطفيلي ويتضرر العائل.","التنافس ليس من أشكال التكافل."]},
  {"q":"الأشنات تتكون من فطر وطحلب وهذه العلاقة مثال على:","o":["التطفل","التعايش","الافتراس","تبادل المنفعة"],"a":3,"why":"الأشنة فطر وطحلب يتشاركان العيش ويستفيد كل منهما من الآخر، فهذه علاقة تبادل المنفعة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["التطفل يتضرر فيه أحد المخلوقين.","في التعايش يستفيد مخلوق واحد فقط.","الافتراس ليس من أشكال التكافل.",""]},
  {"q":"نبات الأوركيد الذي ينمو على الأشجار مثال على:","o":["التطفل","التعايش","تبادل المنفعة","التنافس"],"a":1,"why":"نبات الأوركيد ينمو على الأشجار فيستفيد (مكانًا وضوءًا) ولا يضر الشجرة ولا ينفعها، فهذا تعايش.","ow":["التطفل يتضرر فيه العائل وهذا غير حاصل.","","في تبادل المنفعة يستفيد الاثنان.","التنافس ليس من أشكال التكافل."]},
  {"q":"في التطفل الطفيلي:","o":["يستفيد والعائل يتضرر","يتضرر والعائل يستفيد","لا يستفيد ولا يتضرر","يستفيد والعائل يستفيد"],"a":0,"why":"في التطفل يستفيد الطفيلي ويتضرر العائل. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["","العكس غير صحيح؛ الطفيلي هو الذي يستفيد.","الطفيلي يستفيد ولا يكون بلا فائدة.","العائل لا يستفيد بل يتضرر."]},
  {"q":"الدودة الشريطية مثال على:","o":["العائل","المفترس","الطفيلي","الفريسة"],"a":2,"why":"الدودة الشريطية طفيلي يعيش داخل جسم العائل ويستفيد منه ويضره. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["العائل هو الذي يعيش عليه أو داخله الطفيلي.","المفترس يصطاد الفريسة ولا يعيش داخلها.","","الفريسة حيوان يصطاده المفترس."]},
  {"q":"العبارة: في تبادل المنفعة يستفيد الكائنان معًا.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. في تبادل المنفعة يستفيد الكائنان معًا، مثل النحلة والزهرة. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["","هذه العبارة صحيحة وليست خطأ؛ في تبادل المنفعة يستفيد الكائنان معًا، مثل النحلة والزهرة."]},
  {"q":"العبارة: في التعايش يتضرر أحد المخلوقين.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. في التعايش يستفيد مخلوق ولا يستفيد الآخر ولا يتضرر؛ فلا ضرر على أي منهما.","ow":["هذه العبارة ليست صحيحة؛ في التعايش يستفيد مخلوق ولا يستفيد الآخر ولا يتضرر؛ فلا ضرر على أي منهما.",""]},
  {"q":"العبارة: القراد من الطفيليات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. القراد طفيلي يتغذى على جلد العائل ويستفيد منه ويضره. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["","هذه العبارة صحيحة وليست خطأ؛ القراد طفيلي يتغذى على جلد العائل ويستفيد منه ويضره."]},
  {"q":"العبارة: الماء من العوامل اللاحيوية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الماء من العوامل اللاحيوية لأنه ليس مخلوقًا حيًّا. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الماء من العوامل اللاحيوية لأنه ليس مخلوقًا حيًّا."]},
  {"q":"العبارة: الموطن هو دور المخلوق الحي في النظام البيئي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الموطن هو المكان الذي يعيش فيه المخلوق ويحصل منه على الغذاء؛ أما دور المخلوق فاسمه الإطار البيئي.","ow":["هذه العبارة ليست صحيحة؛ الموطن هو المكان الذي يعيش فيه المخلوق ويحصل منه على الغذاء؛ أما دور المخلوق فاسمه الإطار البيئي.",""]},
];
window.BANK['s5']['s5-3-2'] = [
  {"q":"التكيف هو:","o":["تغيّر المخلوق لمكان آخر","خصائص تركيبية وسلوكية تساعد المخلوق على البقاء في بيئته","نوع من الغذاء","مرحلة من دورة الحياة"],"a":1,"why":"التكيف خصائص تركيبية وسلوكية تساعد المخلوق الحي على البقاء في بيئته. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["تغيّر المكان ليس هو التكيف.","","الغذاء نوع ليس هو التكيف.","مرحلة دورة الحياة ليست هي التكيف."]},
  {"q":"نوعا التكيف هما:","o":["الجنسي واللاجنسي","الكامل والناقص","الداخلي والخارجي","التركيبي والسلوكي"],"a":3,"why":"للتكيف نوعان: تكيف تركيبي (في تركيب الجسم) وتكيف سلوكي (في سلوك المخلوق). ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["الجنسي واللاجنسي نوعا التكاثر.","الكامل والناقص نوعا التحول.","الداخلي والخارجي نوعا الإخصاب.",""]},
  {"q":"التغيّر في تركيب جسم المخلوق يسمى تكيفًا:","o":["سلوكيًّا","تركيبيًّا","وراثيًّا فقط","بيئيًّا"],"a":1,"why":"التغيّر في تركيب جسم المخلوق يسمى تكيفًا تركيبيًّا، مثل خف الجمل وزعانف الفقمة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["التكيف السلوكي تغيّر في سلوك المخلوق.","","الوراثي ليس نوعًا من أنواع التكيف في الدرس.","بيئي ليس نوعًا من أنواع التكيف في الدرس."]},
  {"q":"زعانف الفقمة مثال على التكيف:","o":["السلوكي","الكيميائي","الجنسي","التركيبي"],"a":3,"why":"زعانف الفقمة تغيّر في تركيب جسمها تساعدها على السباحة، فهي تكيف تركيبي. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["التكيف السلوكي تعديل في سلوك المخلوق وليس تركيب جسمه.","التكيف الكيميائي ليس نوعًا من التكيفات في الدرس.","الجنسي ليس نوعًا من أنواع التكيف.",""]},
  {"q":"الحيوان الذي يصطاد حيوانات أخرى يسمى:","o":["المفترس","الفريسة","الطفيلي","العائل"],"a":0,"why":"الحيوان المفترس هو الذي يصطاد حيوانات أخرى ويتغذى عليها. ومن خلاصة الدرس: نباتات وحيوانات متكيفة مع بيئتها.","ow":["","الفريسة هي الحيوان الذي يصطاده المفترس.","الطفيلي يعيش على العائل أو داخله.","العائل هو الذي يعيش عليه الطفيلي."]},
  {"q":"أي مما يأتي من صفات الحيوان المفترس؟","o":["أسنان صغيرة غير حادة","عدم وجود مخالب","حواس قوية وأسنان حادة ومخالب","حواس ضعيفة"],"a":2,"why":"من صفات الحيوان المفترس: حواس قوية وأسنان حادة ومخالب تساعده على الصيد. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الأسنان الصغيرة غير الحادة لا تناسب المفترس.","للمفترس مخالب وليس بلا مخالب.","","الحواس الضعيفة لا تناسب المفترس."]},
  {"q":"اصطياد الذئاب في مجموعات مثال على التكيف:","o":["التركيبي","التلون","السلوكي","التشابه"],"a":2,"why":"اصطياد الذئاب في مجموعات تعديل في سلوكها، فهو تكيف سلوكي. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["التكيف التركيبي تغيّر في تركيب الجسم.","التلون ليس هو المثال هنا؛ الاصطياد في مجموعات سلوك.","","التشابه ليس هو اصطياد الذئاب في مجموعات."]},
  {"q":"السبات الشتوي مثال على التكيف:","o":["السلوكي","التركيبي","التمويه","المحاكاة"],"a":0,"why":"السبات الشتوي تعديل في سلوك الحيوان يحميه من برد الشتاء، فهو تكيف سلوكي. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["","التكيف التركيبي تغيّر في تركيب الجسم وليس السلوك.","التمويه إخفاء المخلوق نفسه في بيئته.","المحاكاة تقليد مخلوق لمخلوق آخر."]},
  {"q":"أي مما يأتي تكيف تركيبي؟","o":["هجرة الطيور","تجمع الذئاب","السبات الشتوي","الفرو السميك"],"a":3,"why":"الفرو السميك تغيّر في تركيب جسم الحيوان يساعده على البقاء، فهو تكيف تركيبي. أما الهجرة والتجمع والسبات فسلوكية.","ow":["هجرة الطيور تكيف سلوكي.","تجمع الذئاب تكيف سلوكي.","السبات الشتوي تكيف سلوكي.",""]},
  {"q":"أي مما يأتي تكيف سلوكي؟","o":["أنياب المفترس","الهجرة في المواسم المختلفة","خف الجمل","زعانف الفقمة"],"a":1,"why":"الهجرة في المواسم المختلفة تكيف سلوكي لأنها تعديل في سلوك المخلوق. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["أنياب المفترس تكيف تركيبي.","","خف الجمل تكيف تركيبي.","زعانف الفقمة تكيف تركيبي."]},
  {"q":"لماذا تكون أزهار بعض النباتات عطرة وزاهية الألوان؟","o":["لتجذب الملقحات","لتطرد الملقحات","لتمنع التلقيح","لتخزن الماء"],"a":0,"why":"بعض أزهار النباتات عطرة وزاهية الألوان لتجذب الملقّحات التي تنقل حبوب اللقاح. ومن خلاصة الدرس: نباتات وحيوانات متكيفة مع بيئتها.","ow":["","الأزهار العطرة الزاهية تجذب الملقّحات ولا تطردها.","هذه الصفات تساعد على التلقيح ولا تمنعه.","تخزين الماء وظيفة ساق الصبار وليس الأزهار."]},
  {"q":"في الغابة المطيرة تتكيف النباتات بوجود:","o":["ساق سميكة تخزن الماء","جذور سطحية فقط","جذور هوائية وأوراق للتخلص من الماء","أوراق صغيرة جدًّا"],"a":2,"why":"النباتات في الغابة المطيرة تتكيف بوجود جذور هوائية وأوراق تتخلص من الماء الزائد. ومن خلاصة الدرس: نباتات وحيوانات متكيفة مع بيئتها.","ow":["الساق السميكة التي تخزن الماء تكيف الصبار في الصحراء.","الجذور السطحية وحدها ليست التكيف الذي يميز الغابة المطيرة.","","الأوراق الصغيرة جدًّا ليست التكيف الذي ذُكر للغابة المطيرة."]},
  {"q":"يعيش نبات الصبار في بيئة:","o":["باردة رطبة","حارة جافة","ماء عذب","غابة مطيرة"],"a":1,"why":"الصبار يعيش في بيئة حارة جافة، ولذلك له ساق سميكة تخزن الماء وجذور سطحية. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["البيئة الباردة الرطبة لا يعيش فيها الصبار.","","الماء العذب ليس بيئة الصبار.","الغابة المطيرة غزيرة الأمطار وليست بيئة الصبار."]},
  {"q":"الجذور السطحية في الصبار تساعده على:","o":["تخزين الغذاء فقط","تثبيته في الجبال","فقد الماء","امتصاص ماء المطر بسرعة"],"a":3,"why":"الجذور السطحية للصبار تمتص ماء المطر بسرعة عند هطوله لأنها قريبة من سطح التربة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الجذور السطحية ليست للتخزين فقط؛ وظيفتها امتصاص ماء المطر بسرعة.","تثبيت الجبال ليس سببًا ذُكر في الدرس.","فقد الماء ليس مفيدًا للصبار.",""]},
  {"q":"تقليد المخلوق لألوان بيئته ليختبئ يسمى:","o":["المحاكاة","التمويه","التطفل","الهجرة"],"a":1,"why":"التمويه أن يتشابه لون المخلوق وشكله مع بيئته ليختبئ من أعدائه. ومن خلاصة الدرس: التمويه – التلون – التشابه – المحاكاة.","ow":["المحاكاة تقليد مخلوق لمخلوق آخر.","","التطفل علاقة يعيش فيها الطفيلي على العائل.","الهجرة انتقال الحيوان في المواسم."]},
  {"q":"تشبّه حيوان بحيوان آخر خطر لإخافة الأعداء يسمى:","o":["التمويه","الهجرة","السبات","المحاكاة"],"a":3,"why":"المحاكاة أن يشبه مخلوق مخلوقًا آخر خطرًا ليخيف أعداءه. ومن خلاصة الدرس: التمويه – التلون – التشابه – المحاكاة.","ow":["التمويه إخفاء المخلوق نفسه في بيئته وليس تقليد مخلوق آخر.","الهجرة تكيف سلوكي لا يتعلق بالتشابه.","السبات تكيف سلوكي لا يتعلق بالتشابه.",""]},
  {"q":"العبارة: هجرة الطيور تكيف سلوكي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. هجرة الطيور تعديل في سلوكها بحسب المواسم، فهي تكيف سلوكي. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["","هذه العبارة صحيحة وليست خطأ؛ هجرة الطيور تعديل في سلوكها بحسب المواسم، فهي تكيف سلوكي."]},
  {"q":"العبارة: أنياب المفترس تكيف سلوكي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. أنياب المفترس جزء من تركيب جسمه، فهي تكيف تركيبي وليست سلوكية. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["هذه العبارة ليست صحيحة؛ أنياب المفترس جزء من تركيب جسمه، فهي تكيف تركيبي وليست سلوكية.",""]},
  {"q":"العبارة: التلون نوع من التمويه.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. التلون (تغيّر لون المخلوق بحسب بيئته) أحد أشكال التمويه الذي يساعد المخلوق على الاختباء.","ow":["","هذه العبارة صحيحة وليست خطأ؛ التلون (تغيّر لون المخلوق بحسب بيئته) أحد أشكال التمويه الذي يساعد المخلوق على الاختباء."]},
  {"q":"العبارة: ساق الصبار رقيقة وتفقد الماء بسرعة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. ساق الصبار سميكة وعليها طبقة شمعية، فتخزن الماء وتمنع فقدانه. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["هذه العبارة ليست صحيحة؛ ساق الصبار سميكة وعليها طبقة شمعية، فتخزن الماء وتمنع فقدانه.",""]},
  {"q":"العبارة: يساعد التكيف المخلوق على البقاء في بيئته.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. التكيف خصائص تركيبية وسلوكية تساعد المخلوق الحي على البقاء في بيئته. ومن خلاصة الدرس: التكيف: تركيبي أو سلوكي.","ow":["","هذه العبارة صحيحة وليست خطأ؛ التكيف خصائص تركيبية وسلوكية تساعد المخلوق الحي على البقاء في بيئته."]},
];
window.BANK['s5']['s5-4-1'] = [
  {"q":"دورة الماء هي:","o":["حركة الماء بين الأرض والهواء","حركة الماء داخل الصخور فقط","حركة الهواء حول الأرض","تجمد الماء فقط"],"a":0,"why":"دورة الماء هي حركة الماء المستمرة بين الأرض والهواء؛ يتبخر ثم يتكثف ثم يهطل فيعود إلى الأرض، وبذلك يُعاد تدويره باستمرار.","ow":["","المياه في الصخور جزء صغير من الدورة وليست الدورة كلها.","حركة الهواء حول الأرض ليست دورة الماء.","تجمّد الماء وحده ليس دورة الماء."]},
  {"q":"تحول الماء من سائل إلى غاز بحرارة الشمس يسمى:","o":["التكثف","الهطول","التبخر","النتح"],"a":2,"why":"تحول الماء من سائل إلى غاز (بخار) بحرارة الشمس يسمى التبخر. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["التكثف هو تحول الغاز إلى سائل.","الهطول سقوط الماء من السحب كمطر أو ثلج أو برد.","","النتح فقد النبات الماء بخارًا من ثغور أوراقه."]},
  {"q":"تحول بخار الماء إلى سائل بالتبريد يسمى:","o":["التبخر","التجمد","التكثف","النتح"],"a":2,"why":"تحول بخار الماء (غاز) إلى سائل بالتبريد يسمى التكثف، وبه تتكوّن قطرات السحاب. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["التبخر عكس التكثف: سائل إلى غاز.","التجمد تحول السائل إلى صلب وليس الغاز إلى سائل.","","النتح فقد الماء من النبات."]},
  {"q":"يتكوّن السحاب من:","o":["قطرات الماء","غاز النيتروجين","الدخان","ثاني أكسيد الكربون"],"a":0,"why":"السحاب يتكوّن من قطرات الماء الصغيرة التي نشأت عن تكثف بخار الماء. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["","غاز النيتروجين لا يكوّن السحاب.","الدخان ليس مكوّن السحاب.","ثاني أكسيد الكربون لا يكوّن السحاب."]},
  {"q":"أي مما يأتي من أشكال الهطول؟","o":["التبخر","التكثف","النتح","البرد"],"a":3,"why":"الهطول يشمل البرد والثلج والمطر وهي صور سقوط الماء من السحب إلى الأرض. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["التبخر تحول الماء السائل إلى غاز وليس سقوطه.","التكثف تحول الغاز إلى سائل وليس سقوطه.","النتح فقد الماء من النبات.",""]},
  {"q":"الماء الذي يجري في الأنهار يسمى:","o":["مياه جوفية","مياه سطحية جارية","ماء مالح فقط","بخار ماء"],"a":1,"why":"الماء الذي يجري في الأنهار يسمى مياهًا سطحية جارية لأنه على سطح الأرض. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["المياه الجوفية داخل الأرض في الصخور.","","الأنهار فيها ماء عذب في الأغلب وليست مالحة فقط.","بخار الماء غاز في الجو وليس ماء الأنهار."]},
  {"q":"المياه الجوفية توجد:","o":["داخل الأرض في الصخور","في السحب","في الأنهار فقط","في الهواء"],"a":0,"why":"المياه الجوفية توجد داخل الأرض في مسامات الصخور والتربة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["","السحب فيها قطرات ماء وليست مياهًا جوفية.","الأنهار فيها المياه السطحية وليس الجوفية.","الهواء فيه بخار ماء وليس مياهًا جوفية."]},
  {"q":"تطلق النباتات الماء بخارًا في الجو عن طريق:","o":["البناء الضوئي","التنفس","النتح","التكثف"],"a":2,"why":"تمتص النباتات الماء بجذورها وتطلقه بخارًا في الجو عن طريق النتح من الثغور. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["البناء الضوئي صنع الغذاء.","التنفس تطلق به الحيوانات الماء لا النباتات في هذا السؤال.","","التكثف تحول بخار الماء إلى سائل في الجو."]},
  {"q":"تطلق الحيوانات الماء في الجو عن طريق:","o":["النتح","التنفس","البناء الضوئي","التلقيح"],"a":1,"why":"تطلق الحيوانات الماء في الجو بخارًا عن طريق التنفس. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["النتح تقوم به النباتات.","","البناء الضوئي تقوم به النباتات لصنع الغذاء.","التلقيح انتقال حبوب اللقاح في الأزهار."]},
  {"q":"أي غاز في الجو مهم في دورة الكربون؟","o":["الأكسجين فقط","النيتروجين","بخار الماء","ثاني أكسيد الكربون"],"a":3,"why":"الغاز المهم في دورة الكربون هو ثاني أكسيد الكربون الموجود في الجو، تمتصه النباتات وتطلقه عمليات أخرى.","ow":["الأكسجين ليس الغاز الأساسي في دورة الكربون.","النيتروجين غاز دورته مختلفة هي دورة النيتروجين.","بخار الماء يتعلق بدورة الماء.",""]},
  {"q":"أي العمليات الآتية تمتص ثاني أكسيد الكربون؟","o":["التنفس","البناء الضوئي","التحلل","حرق الوقود"],"a":1,"why":"البناء الضوئي يمتص ثاني أكسيد الكربون لأن النبات يستعمله في صنع الغذاء. ومن خلاصة الدرس: الكربون: يمتصه النبات ويطلقه التنفس.","ow":["التنفس يطلق ثاني أكسيد الكربون.","","التحلل يطلق ثاني أكسيد الكربون.","حرق الوقود يطلق ثاني أكسيد الكربون."]},
  {"q":"أي العمليات الآتية تطلق ثاني أكسيد الكربون؟","o":["البناء الضوئي","النتح","التكثف","حرق الوقود"],"a":3,"why":"حرق الوقود يطلق ثاني أكسيد الكربون، وكذلك التنفس والتحلل، أما البناء الضوئي فيمتصه. ومن خلاصة الدرس: الكربون: يمتصه النبات ويطلقه التنفس.","ow":["البناء الضوئي يمتص ثاني أكسيد الكربون ولا يطلقه.","النتح فقد ماء من النبات وليس إطلاقًا لثاني أكسيد الكربون.","التكثف تحول بخار الماء إلى سائل.",""]},
  {"q":"يشكل النيتروجين من الهواء نحو:","o":["78%","21%","50%","10%"],"a":0,"why":"النيتروجين يشكل نحو 78% من الهواء، وهو أكثر غازات الجو. ومن خلاصة الدرس: النيتروجين: بكتيريا تحوله لمركبات.","ow":["","21% هي نسبة الأكسجين تقريبًا.","50% نسبة أكبر من الحقيقة.","10% نسبة أقل من الحقيقة."]},
  {"q":"النيتروجين جزء من:","o":["الماء فقط","السكر فقط","البروتينات والمادة الوراثية","الأملاح فقط"],"a":2,"why":"النيتروجين جزء من البروتينات والمادة الوراثية، ولذلك تحتاجه المخلوقات الحية. ومن خلاصة الدرس: النيتروجين: بكتيريا تحوله لمركبات.","ow":["النيتروجين ليس جزءًا من الماء وحده.","النيتروجين ليس جزءًا من السكر وحده.","","النيتروجين ليس جزءًا من الأملاح وحدها."]},
  {"q":"أي المركبات الآتية يمتصه النبات في دورة النيتروجين؟","o":["الأمونيا مباشرة","ثاني أكسيد الكربون","النترات","الأوزون"],"a":2,"why":"النبات يمتص النترات من التربة في دورة النيتروجين، بعد أن تتحول الأمونيا إلى نيتريت ثم نترات.","ow":["الأمونيا لا يمتصها النبات مباشرة بل تتحول أولًا إلى نيتريت ثم نترات.","ثاني أكسيد الكربون غاز تمتصه الأوراق ولا يدخل في دورة النيتروجين.","","الأوزون ليس من مركبات دورة النيتروجين."]},
  {"q":"ماذا تفعل البكتيريا المزيلة للنيتروجين؟","o":["تعيد النيتروجين إلى الهواء","تحول الهواء إلى ماء","تنتج الأكسجين فقط","تمتص الأمونيا"],"a":0,"why":"البكتيريا المزيلة للنيتروجين تعيد النيتروجين إلى الهواء فتكمل دورته. ومن خلاصة الدرس: النيتروجين: بكتيريا تحوله لمركبات.","ow":["","البكتيريا لا تحول الهواء إلى ماء.","البكتيريا لا تنتج الأكسجين فقط.","امتصاص الأمونيا ليس عملها."]},
  {"q":"أي مما يأتي مورد متجدد؟","o":["النفط","الفلزات","الفحم الحجري","الأشجار"],"a":3,"why":"الأشجار مورد متجدد لأنها تنمو وتُزرع من جديد. أما النفط والفلزات والفحم الحجري فموارد غير متجددة.","ow":["النفط مورد غير متجدد.","الفلزات موارد غير متجددة.","الفحم الحجري مورد غير متجدد.",""]},
  {"q":"الدبال مفيد لأنه:","o":["يلوث الماء","يسمّد التربة","يطلق الأوزون","يمنع النتح"],"a":1,"why":"الدبال مفيد لأنه يسمّد التربة ويزيدها خصوبة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الدبال لا يلوث الماء بل يفيد التربة.","","الدبال لا يطلق الأوزون.","الدبال لا يمنع النتح."]},
  {"q":"العبارة: التكثف هو تحول السائل إلى غاز.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. التكثف هو تحول الغاز إلى سائل، أما تحول السائل إلى غاز فهو التبخر. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["هذه العبارة ليست صحيحة؛ التكثف هو تحول الغاز إلى سائل، أما تحول السائل إلى غاز فهو التبخر.",""]},
  {"q":"العبارة: الفلزات من الموارد غير المتجددة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الفلزات موارد غير متجددة لأنها لا تتجدد بالسرعة التي نستعملها، ويمكن إعادة تدويرها.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الفلزات موارد غير متجددة لأنها لا تتجدد بالسرعة التي نستعملها، ويمكن إعادة تدويرها."]},
  {"q":"العبارة: يطلق النتح بخار الماء من النبات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. النتح يطلق بخار الماء من النبات عن طريق الثغور في أوراقه. ومن خلاصة الدرس: الماء: تبخر ← تكثف ← هطول.","ow":["","هذه العبارة صحيحة وليست خطأ؛ النتح يطلق بخار الماء من النبات عن طريق الثغور في أوراقه."]},
  {"q":"العبارة: يطلق البناء الضوئي ثاني أكسيد الكربون.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. البناء الضوئي يمتص ثاني أكسيد الكربون ولا يطلقه؛ أما الذي يطلقه فهو التنفس والتحلل وحرق الوقود.","ow":["هذه العبارة ليست صحيحة؛ البناء الضوئي يمتص ثاني أكسيد الكربون ولا يطلقه؛ أما الذي يطلقه فهو التنفس والتحلل وحرق الوقود.",""]},
  {"q":"العبارة: تتحول البكتيريا المثبتة النيتروجين إلى أمونيا.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. البكتيريا المثبتة للنيتروجين تحوّل غاز النيتروجين إلى أمونيا، ثم تتحول الأمونيا إلى نيتريت ثم نترات.","ow":["","هذه العبارة صحيحة وليست خطأ؛ البكتيريا المثبتة للنيتروجين تحوّل غاز النيتروجين إلى أمونيا، ثم تتحول الأمونيا إلى نيتريت ثم نترات."]},
];
window.BANK['s5']['s5-4-2'] = [
  {"q":"أي مما يأتي حدث طبيعي يغيّر النظام البيئي؟","o":["الفيضانات","قطع الأشجار","بناء الحواجز","التلوث"],"a":0,"why":"الفيضانات حدث طبيعي يغيّر النظام البيئي. أما قطع الأشجار وبناء الحواجز والتلوث فمن فعل الإنسان.","ow":["","قطع الأشجار من فعل الإنسان.","بناء الحواجز من فعل الإنسان.","التلوث من فعل الإنسان."]},
  {"q":"أي مما يأتي من فعل الإنسان ويغيّر النظام البيئي؟","o":["الزلازل","البراكين","قطع الأشجار","الجفاف"],"a":2,"why":"قطع الأشجار من فعل الإنسان ويغيّر النظام البيئي. أما الزلازل والبراكين والجفاف فأحداث طبيعية.","ow":["الزلازل حدث طبيعي.","البراكين حدث طبيعي.","","الجفاف حدث طبيعي."]},
  {"q":"يبني القندس السدود فتتكوّن:","o":["صحراء","بركة","بركان","جبل"],"a":1,"why":"القندس يبني السدود فيتجمع الماء وتتكوّن بركة، فتنشأ مواطن جديدة لمخلوقات أخرى. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["السدود لا تكوّن صحراء.","","السدود لا تكوّن بركانًا.","السدود لا تكوّن جبلًا."]},
  {"q":"المرجان يبني:","o":["السدود","الأعشاش","الكهوف","الشعاب المرجانية"],"a":3,"why":"المرجان يبني الشعاب المرجانية فيغيّر النظام البيئي البحري ويوفر مواطن لمخلوقات كثيرة.","ow":["السدود يبنيها القندس.","الأعشاش تبنيها الطيور وليس المرجان.","الكهوف لا يبنيها المرجان.",""]},
  {"q":"الانقراض هو:","o":["موت فرد واحد من النوع","موت آخر فرد من النوع","هجرة النوع","نمو النوع"],"a":1,"why":"الانقراض هو موت آخر فرد من النوع، فلا يبقى منه أي فرد حي. ومن خلاصة الدرس: الانقراض: موت آخر فرد.","ow":["موت فرد واحد لا يعني انقراض النوع.","","هجرة النوع لا تعني انقراضه.","نمو النوع ليس انقراضًا."]},
  {"q":"الديناصورات مثال على نوع:","o":["مهدد","متكيف","مهاجر","منقرض"],"a":3,"why":"الديناصورات نوع منقرض لأنه لم يعد له أفراد على قيد الحياة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["المهدد لا تزال له أفراد باقية في خطر.","المتكيف نوع لا يزال حيًّا.","المهاجر نوع ينتقل ولا ينقرض.",""]},
  {"q":"الأنواع المهددة بالانقراض هي:","o":["أنواع تتعرض لخطر موت أعداد كبيرة منها","أنواع انقرضت","أنواع لا تتغير","أنواع جديدة"],"a":0,"why":"الأنواع المهددة بالانقراض هي التي تتعرض لخطر موت أعداد كبيرة منها، لكن لا تزال لها أفراد باقية.","ow":["","الأنواع التي انقرضت لم يعد لها أفراد.","المهددة تتأثر وليست بلا تغير.","ليست جديدة بل مهددة بالزوال."]},
  {"q":"أي الحيوانات الآتية من الأنواع المهددة بالانقراض؟","o":["الديناصور","القندس","غزال الريم","الجمل"],"a":2,"why":"غزال الريم من الأنواع المهددة بالانقراض، ومعه المها العربي وسلحفاة منقار الصقر والأرطى.","ow":["الديناصور نوع منقرض وليس مهددًا.","القندس ليس من الأنواع المهددة في الدرس.","","الجمل ليس من الأنواع المهددة في الدرس."]},
  {"q":"من أسباب تهديد الأنواع بالانقراض:","o":["زيادة الغذاء","توفر الموطن","الصيد الجائر","قلة التلوث"],"a":2,"why":"من أسباب تهديد الأنواع بالانقراض الصيد الجائر والتلوث وفقدان الموطن. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["زيادة الغذاء لا تهدد الأنواع.","توفر الموطن يحمي الأنواع ولا يهددها.","","قلة التلوث تحمي الأنواع ولا تهددها."]},
  {"q":"لماذا أنشأت المملكة المحميات الطبيعية؟","o":["لحماية الأنواع المهددة","لزيادة التلوث","لقطع الأشجار","لصيد الحيوانات"],"a":0,"why":"أنشأت المملكة المحميات الطبيعية لحماية الأنواع المهددة بالانقراض. ومن خلاصة الدرس: تغير بأحداث طبيعية أو بفعل الإنسان.","ow":["","المحميات لا تزيد التلوث بل تحمي البيئة.","المحميات تمنع قطع الأشجار ولا تشجعه.","المحميات تحمي الحيوانات ولا تصيدها."]},
  {"q":"التعاقب البيئي هو:","o":["موت النظام البيئي","هجرة الحيوانات فقط","بناء السدود","تغيّر النظام البيئي إلى نظام جديد"],"a":3,"why":"التعاقب البيئي هو تغيّر النظام البيئي إلى نظام جديد، تحلّ فيه أنواع جديدة محل أنواع سابقة.","ow":["التعاقب لا يعني موت النظام البيئي.","هجرة الحيوانات وحدها ليست التعاقب.","بناء السدود تغيير بفعل القندس وليس تعريف التعاقب.",""]},
  {"q":"نوعا التعاقب البيئي:","o":["كامل وناقص","أولي وثانوي","جنسي ولاجنسي","تركيبي وسلوكي"],"a":1,"why":"للتعاقب البيئي نوعان: أولي وثانوي. ومن خلاصة الدرس: تعاقب أولي وثانوي ← مجتمع الذروة.","ow":["كامل وناقص نوعا التحول.","","جنسي ولاجنسي نوعا التكاثر.","تركيبي وسلوكي نوعا التكيف."]},
  {"q":"أولى المخلوقات التي تعيش في منطقة تسمى:","o":["الأنواع الرائدة","مجتمع الذروة","الفرائس","الطفيليات"],"a":0,"why":"أولى المخلوقات التي تعيش في منطقة تسمى الأنواع الرائدة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["","مجتمع الذروة هو المرحلة الأخيرة المستقرة.","الفرائس حيوانات يصطادها المفترس.","الطفيليات تعيش على العائل."]},
  {"q":"يبدأ التعاقب الأولي في منطقة:","o":["فيها تربة وحريق","غابة كاملة","صخور جرداء لا توجد فيها تربة","نهر"],"a":2,"why":"التعاقب الأولي يبدأ في منطقة صخور جرداء لا توجد فيها تربة، فتنمو أولًا الأشنات والحزازيات.","ow":["المنطقة التي فيها تربة وحريق يحدث فيها التعاقب الثانوي.","الغابة الكاملة ليست بداية تعاقب أولي.","","النهر ليس منطقة صخور جرداء."]},
  {"q":"أي مما يأتي صحيح عن التعاقب الثانوي؟","o":["يبدأ بلا تربة","يحدث في منطقة تأثرت ويوجد فيها تربة وهو أسرع","هو أبطأ من الأولي","لا تظهر فيه أشجار"],"a":1,"why":"التعاقب الثانوي يحدث في منطقة تأثرت بحدث ما لكن التربة بقيت فيها، ولذلك يكون أسرع من الأولي.","ow":["التعاقب الثانوي يبدأ بوجود تربة، والأولي هو الذي يبدأ بلا تربة.","","الثانوي أسرع من الأولي وليس أبطأ.","تظهر فيه الأشجار في النهاية."]},
  {"q":"أي المخلوقات تظهر أولًا في التعاقب الأولي؟","o":["الأشجار","الشجيرات","الأعشاب","الأشنات والحزازيات"],"a":3,"why":"في التعاقب الأولي تظهر الأشنات والحزازيات أولًا على الصخور، ثم الأعشاب والشجيرات، ثم الأشجار.","ow":["الأشجار تظهر في النهاية.","الشجيرات تظهر بعد الأعشاب.","الأعشاب تظهر بعد الأشنات والحزازيات.",""]},
  {"q":"المرحلة الأخيرة المستقرة في التعاقب تسمى:","o":["الأنواع الرائدة","مجتمع الذروة","الصدع","الإطار البيئي"],"a":1,"why":"المرحلة الأخيرة المستقرة في التعاقب تسمى مجتمع الذروة. ومن خلاصة الدرس: تعاقب أولي وثانوي ← مجتمع الذروة.","ow":["الأنواع الرائدة هي أول المخلوقات.","","الصدع ليس من مراحل التعاقب.","الإطار البيئي دور المخلوق في موطنه."]},
  {"q":"العبارة: يغيّر القندس النظام البيئي ببناء السدود.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. القندس يبني السدود فتتكوّن بركة ومواطن جديدة، فيغيّر بذلك النظام البيئي.","ow":["","هذه العبارة صحيحة وليست خطأ؛ القندس يبني السدود فتتكوّن بركة ومواطن جديدة، فيغيّر بذلك النظام البيئي."]},
  {"q":"العبارة: سلحفاة منقار الصقر من الأنواع المهددة بالانقراض.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. سلحفاة منقار الصقر من الأنواع المهددة بالانقراض، ومعها المها العربي وغزال الريم والأرطى.","ow":["","هذه العبارة صحيحة وليست خطأ؛ سلحفاة منقار الصقر من الأنواع المهددة بالانقراض، ومعها المها العربي وغزال الريم والأرطى."]},
  {"q":"العبارة: التعاقب الثانوي أبطأ من التعاقب الأولي.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. التعاقب الثانوي أسرع من التعاقب الأولي، لأن التربة موجودة فيه من البداية.","ow":["هذه العبارة ليست صحيحة؛ التعاقب الثانوي أسرع من التعاقب الأولي، لأن التربة موجودة فيه من البداية.",""]},
  {"q":"العبارة: لا توجد تربة في بداية التعاقب الأولي.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. التعاقب الأولي يبدأ في صخور جرداء لا توجد فيها تربة، فتتكوّن التربة تدريجيًّا.","ow":["","هذه العبارة صحيحة وليست خطأ؛ التعاقب الأولي يبدأ في صخور جرداء لا توجد فيها تربة، فتتكوّن التربة تدريجيًّا."]},
  {"q":"العبارة: الزلازل من تغيّرات النظام البيئي بفعل الإنسان.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الزلازل أحداث طبيعية تغيّر النظام البيئي وليست من فعل الإنسان. ومن خلاصة الدرس: تغير بأحداث طبيعية أو بفعل الإنسان.","ow":["هذه العبارة ليست صحيحة؛ الزلازل أحداث طبيعية تغيّر النظام البيئي وليست من فعل الإنسان.",""]},
];
window.BANK['s5']['s5-5-1'] = [
  {"q":"التضاريس هي:","o":["المدن الكبيرة","الطرق والجسور","المباني العالية","المعالم الطبيعية على سطح الأرض"],"a":3,"why":"التضاريس هي المعالم الطبيعية على سطح الأرض مثل الجبال والتلال والسهول والصحاري والبحار والأنهار.","ow":["المدن الكبيرة من صنع الإنسان وليست معالم طبيعية.","الطرق والجسور من صنع الإنسان وليست تضاريس.","المباني العالية من صنع الإنسان وليست تضاريس.",""]},
  {"q":"تنقسم معالم سطح الأرض إلى معالم:","o":["يابسة ومائية","حارة وباردة","قديمة وحديثة","كبيرة وصغيرة"],"a":0,"why":"تنقسم معالم سطح الأرض إلى معالم يابسة (كالجبال والسهول) ومعالم مائية (كالأنهار والبحار).","ow":["","الحرارة والبرودة ليستا تصنيف معالم سطح الأرض.","القديمة والحديثة ليستا تصنيف معالم سطح الأرض.","الكبيرة والصغيرة ليستا تصنيف معالم سطح الأرض."]},
  {"q":"الجبل هو:","o":["منطقة منخفضة بين تلين","منطقة واسعة منبسطة","منطقة مرتفعة كثيرًا","مجرى مائي"],"a":2,"why":"الجبل منطقة مرتفعة كثيرًا عن الأرض المحيطة بها، وهو أعلى من التل. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["المنطقة المنخفضة بين تلين أو جبلين هي الوادي.","المنطقة الواسعة المنبسطة هي السهل.","","المجرى المائي هو النهر وليس الجبل."]},
  {"q":"التل مقارنة بالجبل يكون:","o":["أكثر ارتفاعًا","منبسطًا تمامًا","أقل ارتفاعًا وأكثر استدارة","مليئًا بالماء"],"a":2,"why":"التل أقل ارتفاعًا من الجبل وأكثر استدارة منه. والرمز الصحيح هو الذي تكون فتحته نحو العدد الأكبر.","ow":["التل أقل ارتفاعًا من الجبل وليس أكثر.","التل مرتفع وليس منبسطًا تمامًا.","","التل معلم يابس وليس مليئًا بالماء."]},
  {"q":"المنطقة المنبسطة المرتفعة تسمى:","o":["الهضبة","السهل","الوادي","الدلتا"],"a":0,"why":"الهضبة منطقة منبسطة ومرتفعة، أما السهل فمنبسط وواسع غير مرتفع. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["","السهل منطقة واسعة منبسطة لكنها غير مرتفعة.","الوادي منخفض بين جبلين أو تلين.","الدلتا أرض مثلثة عند مصب النهر."]},
  {"q":"المنطقة الواسعة المنبسطة تسمى:","o":["الجبل","الشلال","الرافد","السهل"],"a":3,"why":"السهل منطقة واسعة منبسطة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الجبل مرتفع جدًّا وليس منبسطًا.","الشلال ماء يسقط من مكان مرتفع.","الرافد نهر صغير يصب في نهر كبير.",""]},
  {"q":"البحر هو:","o":["مجرى مائي طبيعي","مساحة واسعة من المياه المالحة","ماء تحيط به اليابسة","نهر صغير"],"a":1,"why":"البحر مساحة واسعة من المياه المالحة. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["المجرى المائي الطبيعي هو النهر.","","الماء الذي تحيط به اليابسة هو البحيرة.","النهر الصغير الذي يصب في نهر كبير هو الرافد."]},
  {"q":"النهر الصغير الذي يصب في نهر كبير يسمى:","o":["الرافد","الدلتا","الشلال","البحيرة"],"a":0,"why":"الرافد نهر صغير يصب في نهر كبير. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["","الدلتا أرض مثلثة عند مصب النهر.","الشلال ماء يسقط من مكان مرتفع.","البحيرة ماء تحيط به اليابسة."]},
  {"q":"الماء الذي يسقط من مكان مرتفع يسمى:","o":["الرافد","البحيرة","الشلال","الدلتا"],"a":2,"why":"الشلال هو الماء الذي يسقط من مكان مرتفع. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["الرافد نهر صغير يصب في نهر كبير.","البحيرة ماء تحيط به اليابسة.","","الدلتا أرض مثلثة عند مصب النهر."]},
  {"q":"الماء الذي تحيط به اليابسة يسمى:","o":["البحر","البحيرة","النهر","الدلتا"],"a":1,"why":"البحيرة هي الماء الذي تحيط به اليابسة. ومن خلاصة الدرس: التضاريس: معالم يابسة ومائية.","ow":["البحر مساحة واسعة من المياه المالحة.","","النهر مجرى مائي طبيعي.","الدلتا أرض مثلثة عند مصب النهر."]},
  {"q":"المجرى المائي الطبيعي يسمى:","o":["البحيرة","الهضبة","الصفيحة","النهر"],"a":3,"why":"المجرى المائي الطبيعي يسمى النهر. ومن خلاصة الدرس: أغلفة الأرض: جوي – مائي – قشرة – حيوي.","ow":["البحيرة ماء تحيط به اليابسة.","الهضبة معلم يابس مرتفع ومنبسط.","الصفيحة جزء من الغلاف الصخري.",""]},
  {"q":"أي المعالم الآتية يوجد في قاع المحيط؟","o":["الدلتا","الرصيف القاري","الهضبة","الشلال"],"a":1,"why":"الرصيف القاري من معالم قاع المحيط، ومعه المنحدر القاري والمرتفع القاري والأخاديد البحرية والسهول القاعية والجبال البحرية.","ow":["الدلتا معلم عند مصب النهر على اليابسة.","","الهضبة معلم يابس.","الشلال معلم في النهر على اليابسة."]},
  {"q":"الغلاف المائي هو:","o":["الغلاف الغازي","الجزء الصخري الصلب","مكان المخلوقات الحية","الماء بكل حالاته"],"a":3,"why":"الغلاف المائي هو الماء بكل حالاته (سائل وصلب وغاز)، ويغطي نحو 7/10 من سطح الأرض. ومن خلاصة الدرس: أغلفة الأرض: جوي – مائي – قشرة – حيوي.","ow":["الغلاف الغازي هو الغلاف الجوي.","الجزء الصخري الصلب هو القشرة الأرضية.","مكان المخلوقات الحية هو الغلاف الحيوي.",""]},
  {"q":"القشرة الأرضية هي:","o":["الجزء الصخري الصلب","الغلاف الغازي","الماء بكل حالاته","طبقة اللب"],"a":0,"why":"القشرة الأرضية هي الجزء الصخري الصلب من الأرض الذي نعيش عليه. ومن خلاصة الدرس: أغلفة الأرض: جوي – مائي – قشرة – حيوي.","ow":["","الغلاف الغازي هو الغلاف الجوي.","الماء بكل حالاته هو الغلاف المائي.","اللب طبقة داخل الأرض وليس القشرة."]},
  {"q":"الطبقة التي تلي القشرة الأرضية من الداخل هي:","o":["اللب الداخلي","اللب الخارجي","الستار العلوي","الستار السفلي"],"a":2,"why":"ترتيب طبقات الأرض من الخارج: القشرة ثم الستار العلوي ثم الستار السفلي ثم اللب الخارجي ثم اللب الداخلي. فالطبقة التي تلي القشرة هي الستار العلوي.","ow":["اللب الداخلي أعمق طبقة في الأرض.","اللب الخارجي يأتي بعد الستار السفلي.","","الستار السفلي يأتي بعد الستار العلوي."]},
  {"q":"اللب الداخلي للأرض:","o":["سائل","غازي","صلب","مائي"],"a":2,"why":"اللب الداخلي للأرض صلب، بينما اللب الخارجي سائل. راجع هذه الفكرة من الدرس لتتذكّرها في الأسئلة المشابهة.","ow":["اللب الخارجي هو السائل.","اللب الداخلي ليس غازيًّا.","","اللب الداخلي ليس مائيًّا بل صخورًا صلبة."]},
  {"q":"الغلاف الصخري يتكوّن من:","o":["القشرة وجزء من الستار العلوي","الستار السفلي واللب","القشرة والغلاف الجوي","الماء والهواء"],"a":0,"why":"الغلاف الصخري يتكوّن من القشرة الأرضية وجزء من الستار العلوي، وينقسم إلى صفائح. ومن خلاصة الدرس: طبقات: قشرة – ستار – لب.","ow":["","الستار السفلي واللب ليسا من الغلاف الصخري.","القشرة والغلاف الجوي لا يكوّنان الغلاف الصخري.","الماء والهواء ليسا مكوّنين للغلاف الصخري."]},
  {"q":"العبارة: تطفو الصفائح الأرضية فوق الغلاف المائع.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الغلاف الصخري ينقسم إلى صفائح تطفو فوق الغلاف المائع الذي تحتها، وحركتها تكوّن المحيطات والجبال.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الغلاف الصخري ينقسم إلى صفائح تطفو فوق الغلاف المائع الذي تحتها، وحركتها تكوّن المحيطات والجبال."]},
  {"q":"العبارة: الوادي منطقة مرتفعة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الوادي منطقة منخفضة بين جبلين أو تلين، وليس منطقة مرتفعة. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["هذه العبارة ليست صحيحة؛ الوادي منطقة منخفضة بين جبلين أو تلين، وليس منطقة مرتفعة.",""]},
  {"q":"العبارة: يغطي الغلاف المائي نحو 3/10 من سطح الأرض.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ. الغلاف المائي يغطي نحو 7/10 من سطح الأرض وليس 3/10 فقط. ومن خلاصة الدرس: أغلفة الأرض: جوي – مائي – قشرة – حيوي.","ow":["هذه العبارة ليست صحيحة؛ الغلاف المائي يغطي نحو 7/10 من سطح الأرض وليس 3/10 فقط.",""]},
  {"q":"العبارة: تتكوّن الدلتا عند مصب النهر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. الدلتا أرض لها شكل مثلث تتكوّن عند مصب النهر. راجع القاعدة في الدرس وطبّقها على المثال خطوة خطوة للتأكد.","ow":["","هذه العبارة صحيحة وليست خطأ؛ الدلتا أرض لها شكل مثلث تتكوّن عند مصب النهر."]},
  {"q":"العبارة: حركة الصفائح الأرضية تسهم في تكوّن الجبال والمحيطات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة. حركة الصفائح الأرضية تكوّن المحيطات والجبال، مثل البحر الأحمر. ومن خلاصة الدرس: حركة الصفائح تكوّن المحيطات والجبال.","ow":["","هذه العبارة صحيحة وليست خطأ؛ حركة الصفائح الأرضية تكوّن المحيطات والجبال، مثل البحر الأحمر."]},
];
